  --sc-ui-text-muted: rgba(0, 0, 0, 0.45);
  --sc-ui-text-on-primary: #fff;
  --sc-ui-bg: #fff;
  --sc-ui-bg-subtle: #f8f8f8;
  --sc-ui-surface: #fff;
  --sc-ui-surface-border: rgba(0, 0, 0, 0.08);
  --sc-ui-surface-shadow-1: 0 8px 24px rgba(0, 0, 0, 0.08);
  --sc-ui-surface-shadow-2: 0 2px 8px rgba(0, 0, 0, 0.04);
  --sc-ui-hover: rgba(0, 0, 0, 0.04);
  --sc-ui-active: rgba(0, 0, 0, 0.08);
  --sc-ui-focus-ring: rgba(41, 114, 244, 0.3);
  --sc-ui-border: rgba(0, 0, 0, 0.08);
  --sc-ui-separator: rgba(0, 0, 0, 0.06);
  --sc-ui-primary: #2972f4;
  --sc-ui-primary-hover: #1d5fd4;
  --sc-ui-primary-active: #1750b8;
  --sc-ui-danger: #e53e3e;
  /* Toast 等反馈组件的语义色（success / warning / info）。命名沿用 antd / material 体系，
   * 不进入 button / link 等基础组件的样式 token，避免概念膨胀。 */
  --sc-ui-success: #10b981;
  --sc-ui-warning: #f59e0b;
  --sc-ui-info: #2972f4;
  /* 与 primary 同色，但语义独立可独立换 */
  --sc-ui-disabled-opacity: 0.35;
  /* 圆角 */
  --sc-ui-radius-sm: 4px;
  --sc-ui-radius-md: 6px;
  --sc-ui-radius-lg: 10px;
}
/* ── Dark 模式 Token ── */
:root[data-sc-color-scheme='dark'] {
  --sc-ui-text: rgba(255, 255, 255, 0.85);
  --sc-ui-text-muted: rgba(255, 255, 255, 0.45);
  --sc-ui-text-on-primary: #fff;
  --sc-ui-bg: #1e1e1e;
  --sc-ui-bg-subtle: #2a2a2a;
  --sc-ui-surface: #252525;
  --sc-ui-surface-border: rgba(255, 255, 255, 0.08);
  --sc-ui-surface-shadow-1: 0 8px 24px rgba(0, 0, 0, 0.32);
  --sc-ui-surface-shadow-2: 0 2px 8px rgba(0, 0, 0, 0.2);
  --sc-ui-hover: rgba(255, 255, 255, 0.06);
  --sc-ui-active: rgba(255, 255, 255, 0.12);
  --sc-ui-focus-ring: rgba(41, 114, 244, 0.4);
  --sc-ui-border: rgba(255, 255, 255, 0.08);
  --sc-ui-separator: rgba(255, 255, 255, 0.06);
  --sc-ui-primary: #4d94ff;
  --sc-ui-primary-hover: #3a80e8;
  --sc-ui-primary-active: #2c6fd4;
  --sc-ui-danger: #fc8181;
  /* Dark 模式下提升对比度（饱和度略升、亮度上调） */
  --sc-ui-success: #34d399;
  --sc-ui-warning: #fbbf24;
  --sc-ui-info: #4d94ff;
}
/* ── 弹出动画 keyframes ── */
@keyframes scui-fade-in {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes scui-fade-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.96);
  }
}
/* ── 极简滚动条 ── */
.scui-scrollable {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.scui-scrollable:hover {
  scrollbar-color: rgba(0, 0, 0, 0.15) transparent;
}
.scui-scrollable::-webkit-scrollbar {
  width: 4px;
}
.scui-scrollable::-webkit-scrollbar-track {
  background: transparent;
}
.scui-scrollable::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: 4px;
}
.scui-scrollable:hover::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.15);
}
:root[data-sc-color-scheme='dark'] .scui-scrollable:hover {
  scrollbar-color: rgba(255, 255, 255, 0.15) transparent;
}
:root[data-sc-color-scheme='dark'] .scui-scrollable:hover::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
}
/* ── Content 容器 ── */
.sc-dropdown-content {
  z-index: 100;
  min-width: 200px;
  max-height: 400px;
  overflow-y: auto;
  background: var(--sc-ui-surface);
  border: 0.5px solid var(--sc-ui-surface-border);
  border-radius: 8px;
  box-shadow: var(--sc-ui-surface-shadow-1), var(--sc-ui-surface-shadow-2);
  padding: 4px;
  /* 弹出动画 */
  animation: scui-fade-in 0.15s ease-out;
  /* 极简滚动条 */
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.sc-dropdown-content[data-state='closed'] {
  animation: scui-fade-out 0.1s ease-in;
}
.sc-dropdown-content:hover {
  scrollbar-color: rgba(0, 0, 0, 0.15) transparent;
}
.sc-dropdown-content::-webkit-scrollbar {
  width: 4px;
}
.sc-dropdown-content::-webkit-scrollbar-track {
  background: transparent;
}
.sc-dropdown-content::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: 4px;
}
.sc-dropdown-content:hover::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.15);
}
.sc-dropdown-sub-content {
  min-width: 220px;
}
/* ── Item ── */
.sc-dropdown-item,
.sc-dropdown-sub-trigger {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 6px 8px;
  min-height: 32px;
  border: none;
  background: transparent;
  cursor: pointer;
  font-size: 14px;
  line-height: 20px;
  color: var(--sc-ui-text);
  text-align: left;
  outline: none;
  border-radius: var(--sc-ui-radius-md);
  transition: background 0.1s ease;
}
.sc-dropdown-item[data-highlighted],
.sc-dropdown-sub-trigger[data-highlighted] {
  background: var(--sc-ui-hover);
}
.sc-dropdown-item[data-disabled],
.sc-dropdown-sub-trigger[data-disabled] {
  opacity: var(--sc-ui-disabled-opacity);
  cursor: not-allowed;
}
.sc-dropdown-item-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  color: var(--sc-menu-icon-color, var(--sc-ui-text-muted));
  flex-shrink: 0;
}
.sc-dropdown-item-icon svg {
  width: 16px;
  height: 16px;
}
.sc-dropdown-item-label {
  flex: 1;
}
.sc-dropdown-item-shortcut {
  font-size: 12px;
  color: var(--sc-ui-text-muted);
  margin-left: auto;
  letter-spacing: 0.02em;
}
.sc-dropdown-item-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  color: var(--sc-ui-text-muted);
  margin-left: auto;
  /* 设计规范箭头（实心 chevron）原始比例 5.27 : 8.85，保持原始尺寸，
   * 禁止强制 12×12 正方形拉伸变形 */
}
.sc-dropdown-item-arrow svg {
  width: 5.2727px;
  height: 8.8486px;
}
.sc-dropdown-item-check {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  color: var(--sc-menu-check-color, var(--sc-ui-primary));
  margin-left: auto;
  flex-shrink: 0;
}
/* ── Separator ── */
.sc-dropdown-separator {
  height: 1px;
  margin: 4px 0;
  background: var(--sc-ui-separator);
}
/* ── Danger variant ── */
.sc-dropdown-item--danger {
  color: var(--sc-ui-danger);
}
.sc-dropdown-item--danger .sc-dropdown-item-icon {
  color: var(--sc-ui-danger);
}
/* ── Label ── */
.sc-dropdown-label {
  padding: 8px 10px 4px;
  font-size: 12px;
  line-height: 16px;
  color: var(--sc-ui-text-muted);
  font-weight: 500;
}
/* ── Dark 模式滚动条 ── */
:root[data-sc-color-scheme='dark'] .sc-dropdown-content:hover {
  scrollbar-color: rgba(255, 255, 255, 0.15) transparent;
}
:root[data-sc-color-scheme='dark'] .sc-dropdown-content:hover::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
}
