  top: 0;
  left: 0;
  width: var(--sc-code-block-padding-inline-left);
  padding-top: var(--sc-code-block-padding-block);
  pointer-events: none;
  user-select: none;
}
.sc-block-code .sc-code-line-number {
  position: absolute;
  left: var(--sc-code-line-number-inset);
  color: var(--sc-text-grey);
}
.sc-block-code .sc-code-editable {
  display: block;
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: var(--sc-code-block-font-family, var(--sc-font-family-mono));
  tab-size: 4;
  white-space: pre;
  word-break: normal;
  overflow-wrap: normal;
