    background: var(--sc-ui-active);
  }
}
.sc-link-edit-btn.is-confirm {
  background: var(--sc-ui-primary);
  color: var(--sc-ui-text-on-primary);
}
@media (hover: hover) {
  .sc-link-edit-btn.is-confirm:hover {
    background: var(--sc-ui-primary-hover);
  }
}
/**
 * Floating Toolbar 样式
 */
.sc-floating-toolbar {
