.sc-block-menu-content.sc-dropdown-content {
  width: fit-content;
  min-width: 176px;
  max-height: var(--radix-dropdown-menu-content-available-height, 560px);
  overflow-y: auto;
  padding: 12px 8px;
  /* 覆盖 .sc-dropdown-content 基类的 8px（对齐 ardot 菜单面板圆角，
   * 与 toc 悬浮目录面板一致）；复合选择器特异性 0-2-0，同时命中
   * block 菜单 Content 与二级菜单 SubContent（均带 sc-block-menu-content 类） */
  border-radius: var(--sc-menu-panel-radius);
  /* 菜单底色接入 --sc-menu-surface token（划词工具栏系已消费），
   * 覆盖基类 --sc-ui-surface，使菜单系浮层底色可一处统一覆盖 */
  background: var(--sc-menu-surface, var(--sc-ui-surface));
  /* 阴影三件套：接入 --sc-menu-shadow（设计稿 wb/shadow/Popup-Medium），
   * 覆盖基类 --sc-ui-surface-shadow-1/2 重阴影 */
  box-shadow: var(--sc-menu-shadow);
}
/* 顶部类型快捷切换网格（样式对齐 CommandGrid：5 列、无边框、hover 背景） */
.sc-block-menu-type-grid {
  display: grid;
  grid-template-columns: repeat(5, 24px);
  gap: 8px;
  padding: 0 0 8px;
  justify-content: start;
  border-bottom: 1px solid var(--sc-ui-separator);
  margin-bottom: 8px;
}
.sc-block-menu-type-grid-item {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  background: transparent;
  border-radius: var(--sc-ui-radius-sm, 4px);
  color: var(--sc-cmd-text-muted, var(--sc-menu-icon-color));
  cursor: pointer;
  transition: background 0.1s ease;
}
.sc-block-menu-type-grid-item > svg {
  width: var(--sc-menu-icon-size);
  height: var(--sc-menu-icon-size);
}
@media (hover: hover) {
  .sc-block-menu-type-grid-item:hover {
    background: var(--sc-cmd-hover, var(--sc-menu-hover-bg));
  }
}
.sc-block-menu-type-grid-item.is-active {
  background: var(--sc-cmd-active, var(--sc-menu-active-bg));
  color: var(--sc-cmd-primary, var(--sc-menu-icon-color-active));
}
/* 颜色子菜单：分组小标题（非 Radix Label，禁止聚焦） */
.sc-block-menu-section-label {
  padding: 8px 10px 4px;
  font-size: var(--sc-menu-font-size-sm);
  line-height: 16px;
  color: var(--sc-menu-text-color-muted);
  font-weight: 500;
  pointer-events: none;
}
/* Block menu 静态展示项（disabled）： 置灰、不响应交互 */
.sc-block-menu-content .sc-dropdown-item[data-disabled] {
  cursor: not-allowed;
  opacity: 0.4;
}
.sc-block-menu-content .sc-dropdown-item[data-disabled]:hover,
.sc-block-menu-content .sc-dropdown-item[data-disabled][data-selected='true'],
.sc-block-menu-content .sc-dropdown-item[data-disabled][data-highlighted] {
  background: transparent;
}
/* 颜色子菜单：色块预览 */
.sc-block-menu-color-swatch {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border-radius: 3px;
  border: 1px solid var(--sc-ui-border, rgba(0, 0, 0, 0.08));
  font-size: 12px;
  line-height: 1;
  font-weight: 600;
}
/* 字体色：白底 + 字母 A 显示为目标色 */
.sc-block-menu-color-swatch--font {
  background: var(--sc-ui-surface, #ffffff);
}
/* ── 面板容器 ──
 * 面板 absolute 定位在 EditorOverlay 内（EditorOverlay 是 .sc-editor 的子元素）。
 * 当 EditorRoot 启用 containerScroll 时，滚动收敛到 .sc-editor-content 内层，
 * EditorOverlay 不参与内容滚动 → 面板天然钉在 .sc-editor 视觉右上角。
 */
.sc-search-panel {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 50;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 8px;
  /* 响应式宽度：理想 360px，但窄视口（移动端 / 分屏）下不能溢出编辑器；
   * 父级 EditorOverlay 宽度 = .sc-editor 宽度，预留 24px 给 top/right margin 共 12px*2 */
  min-width: min(360px, calc(100% - 24px));
  max-width: calc(100vw - 24px);
  background: var(--sc-ui-surface);
  border: 1px solid var(--sc-ui-surface-border);
  border-radius: var(--sc-ui-radius-lg);
  box-shadow: var(--sc-ui-surface-shadow-1);
  color: var(--sc-ui-text);
  /* 面板自身要参与编辑器内点击事件，但不要阻塞父级 EditorOverlay 的 pointer-events */
  pointer-events: auto;
}
/* ── 单行（搜索行 / 替换行） ── */
.sc-search-panel__row {
  display: flex;
  align-items: center;
  gap: 4px;
}
/* 替换行（在 find 模式下条件渲染消失，replace 模式下出现）— 加滑入动画避免生硬切换 */
.sc-search-panel__row.is-replace-row {
  animation: sc-search-replace-row-in 0.16s cubic-bezier(0.16, 1, 0.3, 1);
  transform-origin: top;
}
@keyframes sc-search-replace-row-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scaleY(0.92);
    max-height: 0;
  }
  to {
    opacity: 1;
    transform: translateY(0) scaleY(1);
    max-height: 60px;
  }
}
/* ── 输入框 ── */
.sc-search-panel__input {
  flex: 1 1 auto;
  min-width: 120px;
  height: 28px;
  padding: 0 8px;
  background: var(--sc-ui-bg-subtle);
  border: 1px solid transparent;
  border-radius: var(--sc-ui-radius-md);
  color: var(--sc-ui-text);
  font-size: 13px;
  line-height: 26px;
  outline: none;
  transition: border-color 0.12s ease;
}
.sc-search-panel__input::placeholder {
  color: var(--sc-ui-text-muted);
}
.sc-search-panel__input:focus {
  border-color: var(--sc-ui-primary);
}
/* ── 计数文本 ── */
.sc-search-panel__count {
  flex: 0 0 auto;
  min-width: 48px;
  padding: 0 4px;
  font-size: 12px;
  line-height: 28px;
  color: var(--sc-ui-text-muted);
  text-align: right;
  user-select: none;
  white-space: nowrap;
}
/* ── 操作按钮组 ── */
.sc-search-panel__actions {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}
/* ── 单个按钮 ── */
.sc-search-panel__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  height: 26px;
  padding: 0 6px;
  background: transparent;
  border: none;
  border-radius: var(--sc-ui-radius-sm);
  color: var(--sc-ui-text);
  font-size: 12px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.12s ease;
  user-select: none;
  /* Aa toggle 激活态：用主色文字 + 浅底凸显 */
}
@media (hover: hover) {
  .sc-search-panel__button:hover:not(:disabled) {
    background: var(--sc-ui-hover);
  }
}
.sc-search-panel__button:active:not(:disabled) {
  background: var(--sc-ui-active);
}
.sc-search-panel__button:disabled {
  opacity: var(--sc-ui-disabled-opacity);
  cursor: default;
}
.sc-search-panel__button.is-case-active {
  background: var(--sc-ui-active);
  color: var(--sc-ui-primary);
  font-weight: 600;
}
/* ── 搜索高亮（CSS Custom Highlight API） ── */
/* 命中淡黄底，当前命中橙色加深；多 editor 实例由 JS 注入实际 highlight name 后缀，
   但样式按通用 highlight 名字一次性铺开仍然命中（::highlight 接受任意 ident）。
   为了简洁，这里用通配前缀写两套规则覆盖；具体实例的 highlight 名前缀已隔离，
   不会跨实例串色。 */
/* 由于 ::highlight() 不支持通配，下面直接列出最常见的 N 个实例后缀；
   实际生产中 editor 实例数极少，且 createSearchHighlight 句柄在卸载时会 delete
   注册名，浏览器对未匹配的 ::highlight 名静默忽略。
   编辑器内通常只有 1 个实例：sc-search-match-{8 位 hex}。
   这里用 attribute selector 无法实现 ::highlight 通配，采用 CSS-in-JS 注入更复杂；
   保守做法：在 EditorRoot 内部注入一段 \3c style> 仅包含本实例的两个 highlight 规则。 */
.sc-link-hover-card {
  position: absolute;
  display: flex;
  align-items: center;
  padding: var(--sc-menu-padding-y) var(--sc-menu-padding-x);
  background: var(--sc-menu-surface);
  border: var(--sc-menu-border-width) solid var(--sc-menu-border-color);
  border-radius: var(--sc-menu-radius);
  box-shadow: var(--sc-menu-shadow);
  user-select: none;
  white-space: nowrap;
  pointer-events: all;
}
.sc-link-hover-card .sc-btn--ghost {
  color: var(--sc-menu-icon-color);
}
.sc-link-hover-row {
  display: flex;
  align-items: center;
  gap: var(--sc-menu-gap);
}
.sc-link-hover-open.sc-btn {
  color: var(--sc-menu-text-color);
  font-weight: 400;
  height: 24px;
  padding: 0 8px;
  border-radius: var(--sc-ui-radius-md);
  font-size: var(--sc-menu-font-size);
}
.sc-link-hover-btn {
  width: 24px;
  height: 24px;
  min-width: 24px;
  padding: 4px;
  border-radius: var(--sc-ui-radius-md);
  border: none;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.1s;
}
.sc-link-hover-btn svg {
  width: var(--sc-menu-icon-size);
  height: var(--sc-menu-icon-size);
}
@media (hover: hover) {
  .sc-link-hover-btn:hover {
    background: var(--sc-menu-hover-bg);
  }
}
.sc-link-hover-sep {
  display: inline-block;
  width: 1px;
  height: var(--sc-menu-separator-height);
  background: var(--sc-menu-separator-color);
  margin: 0 4px;
}
/* ── Page Root View 样式 ── */
/* 对应 view/runtime/page-root-view/ 下的组件 */
/* Page 根节点 = CN.page.root（'sc-page'）。
 * 会话级几何缩放，与 --sc-font-scale 正交。宿主对 .sc-page 写 CSS zoom 时，
 * 必须在同一节点同步 --sc-view-zoom（表格控件用 var(--sc-view-zoom, 1) 反算）。
 *
 * 此处刻意不声明 `--sc-view-zoom: 1`。宿主也可能把 zoom 与 --sc-view-zoom 一起
 * 写在本节点的外层（如 .sc-editor-content，见 view-zoom.less）；一旦这里显式写 1，
 * 继承值会被屏蔽，控件层的 zoom: calc(1 / var(--sc-view-zoom, 1)) 退化成 1，
 * 控件却仍处在外层 zoom 的树里，位置会随外层缩放整体偏移（拖拽指示线对不上
 * 真实分割线）。宿主未设置时，各使用处的 var(--sc-view-zoom, 1) 自带回退值 1。 */
.sc-page-body {
  display: block;
  /* 底部留白移到 .sc-page-bottom 之后（margin-bottom），
   * 让 page-bottom 的内容紧跟正文，符合"内容末尾的页脚"语义 */
  padding-bottom: 0;
}
/**
 * Page 底部常驻 slot —— 与正文同宽居中，供插件作为底部面板挂载点。
 * 默认无内边距、无视觉表现；插件挂载内容后由插件自身控制样式。
 *
 * margin-bottom: 30vh 保留底部空白点击区（原本 .sc-page-body 的留白）。
 * 使用 CSS 变量允许外部定制。
 */
.sc-page-bottom {
  display: block;
  max-width: 860px;
  margin: 0 auto var(--sc-page-body-padding-bottom, 30vh);
}
/* title/icon/cover 均隐藏时，内容区与顶部保持间距 */
.sc-page-body.sc-page-body--no-header {
  padding-top: var(--sc-page-body-padding-top, 32px);
}
.sc-page-body,
.sc-page-title,
.sc-page-icon {
  max-width: 860px;
  margin: 0 auto;
}
/* page 首层 children 不缩进 */
.sc-page-body > .sc-block-children[data-layout='indented'] {
  padding-left: 0;
}
/* 空页面 placeholder —— 纯视觉提示，模拟第一个 text block 的布局位置 */
.sc-page-body-placeholder {
  color: var(--sc-ui-text-muted, rgba(0, 0, 0, 0.45));
  font-size: var(--sc-content-font-size);
  cursor: text;
  user-select: none;
  pointer-events: none;
  /* 对齐 .sc-block 的 margin，避免 block 创建后位置跳动 */
  margin-top: var(--sc-block-gap, 8px);
  margin-bottom: var(--sc-block-gap, 8px);
  line-height: var(--sc-content-line-height);
}
/* ── Page Header ── */
/* 当 header 前面没有 icon/placeholder/extra-actions 时（只读且无 icon，或功能禁用），
 * 由 header 自身提供顶部间距。
 * 当前面有 sc-page-icon 或 sc-page-extra-actions 时，间距已由它们提供，header 不再加。 */
.sc-page-header.without-page-cover {
  margin-top: var(--sc-page-top-spacing, 60px);
}
.sc-page-header.with-page-cover {
  margin-top: var(--sc-page-top-spacing-with-cover, 16px);
}
/* icon / placeholder / extra-actions 紧接着 header 时，header 不需要自己的 margin-top */
.sc-page-icon + .sc-page-header,
.sc-page-extra-actions + .sc-page-header,
.sc-page-icon + .sc-page-extra-actions + .sc-page-header {
  margin-top: 0;
}
.sc-page-title {
  margin-top: 2px;
  margin-bottom: 48px;
  font-family: var(--sc-content-font-family);
  font-size: var(--sc-page-title-font-size);
  line-height: var(--sc-page-title-line-height);
  font-weight: var(--sc-content-font-weight-bold);
}
/* ── Page Cover ── */
.sc-page-cover {
  height: 30vh;
  max-height: 400px;
  position: relative;
  margin-inline: calc(var(--sc-editor-padding-left) * -1) calc(var(--sc-editor-padding-right) * -1);
  margin-top: calc(var(--sc-editor-padding-top) * -1);
  width: calc(100% + var(--sc-editor-padding-left) + var(--sc-editor-padding-right));
  user-select: none;
  /* 调整位置态：cursor 提示 + 图片可拖拽 + 顶层蒙层 */
}
.sc-page-cover .sc-page-cover-img {
  height: 100%;
  width: 100%;
  object-position: center 50%;
  object-fit: cover;
  pointer-events: none;
}
.sc-page-cover .sc-page-cover-fill {
  height: 100%;
  width: 100%;
}
.sc-page-cover.is-reposition {
  cursor: grab;
  /* 调整位置态加一层细边框，强化"进入编辑"反馈 */
}
.sc-page-cover.is-reposition.is-dragging {
  cursor: grabbing;
}
.sc-page-cover.is-reposition .sc-page-cover-img {
  pointer-events: auto;
}
.sc-page-cover.is-reposition::after {
  content: '';
  position: absolute;
  inset: 0;
  border: 2px solid var(--sc-ui-accent, #2f80ed);
  pointer-events: none;
}
/* 右下角浮层工具条：默认隐藏，hover 容器或工具条自身时显示 */
.sc-page-cover-actions {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: flex;
  gap: 4px;
  padding: 4px;
  background: rgba(255, 255, 255, 0.95);
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  opacity: 0;
  transition: opacity 0.15s;
}
.sc-page-cover:hover .sc-page-cover-actions,
.sc-page-cover-actions:hover {
  opacity: 1;
}
.sc-page-cover-action-btn {
  border: none;
  background: transparent;
  color: var(--sc-ui-text-primary, #333);
  font-size: 12px;
  padding: 4px 8px;
  border-radius: 4px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s;
}
@media (hover: hover) {
  .sc-page-cover-action-btn:hover {
    background: var(--sc-ui-surface-hover, rgba(0, 0, 0, 0.06));
  }
}
.sc-page-cover-action-btn.is-primary {
  background: var(--sc-ui-accent, #2f80ed);
  color: #fff;
}
@media (hover: hover) {
  .sc-page-cover-action-btn.is-primary:hover {
    background: var(--sc-ui-accent-hover, #1f70dd);
  }
}
/* 调整位置态：底部 hint + 保存按钮 */
.sc-page-cover-reposition-bar {
  position: absolute;
  left: 50%;
  bottom: 12px;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 6px 10px;
  background: rgba(0, 0, 0, 0.7);
  color: #fff;
  border-radius: 6px;
  font-size: 12px;
  pointer-events: auto;
  z-index: 10;
}
.sc-page-cover-reposition-hint {
  white-space: nowrap;
}
.sc-page-cover-reposition-btn {
  border: none;
  background: rgba(255, 255, 255, 0.2);
  color: #fff;
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 4px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s;
}
@media (hover: hover) {
  .sc-page-cover-reposition-btn:hover {
    background: rgba(255, 255, 255, 0.3);
  }
}
.sc-page-cover-reposition-btn.is-primary {
  background: var(--sc-ui-accent, #2f80ed);
  color: #fff;
}
@media (hover: hover) {
  .sc-page-cover-reposition-btn.is-primary:hover {
    background: var(--sc-ui-accent-hover, #1f70dd);
  }
}
/* ── Cover Picker 弹窗 ── */
.sc-cover-picker-popover {
  z-index: 1000;
  padding: 0;
  border: none;
  max-height: var(--radix-popover-content-available-height);
  overflow: hidden;
}
.sc-cover-picker {
  width: 552px;
  max-height: inherit;
  display: flex;
  flex-direction: column;
  background: var(--sc-ui-surface, #fff);
  border-radius: 8px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
  overflow: hidden;
}
.sc-cover-picker__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px 0;
  flex-shrink: 0;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.04);
  /* picker 内去掉 Tabs 默认下划线与底部 margin，让 header 整体白底干净 */
}
.sc-cover-picker__header .sc-tabs-list {
  border-bottom: none;
  margin-bottom: 0;
}
.sc-cover-picker__remove {
  padding: 4px 10px;
  font-size: 12px;
  border: none;
  background: var(--sc-ui-hover);
  color: var(--sc-ui-text);
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
@media (hover: hover) {
  .sc-cover-picker__remove:hover {
    background: var(--sc-ui-active);
  }
}
.sc-cover-picker__body {
  padding: 12px 16px 16px;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  /* Radix Tabs.Content 是 picker__body 的直接子节点（active panel），让它撑满 body */
}
.sc-cover-picker__body > [role='tabpanel'] {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
/* Gallery Tab */
.sc-cover-picker__gallery {
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex: 1;
  min-height: 0;
  max-height: 432px;
  overflow-y: auto;
}
.sc-cover-picker__section-title {
  font-size: 12px;
  color: var(--sc-ui-text-tertiary, #999);
  margin-bottom: 8px;
  font-weight: 500;
}
.sc-cover-picker__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}
.sc-cover-picker__item {
  position: relative;
  height: 69px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  background-repeat: no-repeat;
  padding: 0;
  overflow: hidden;
}
.sc-cover-picker__item::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.16);
  opacity: 0;
  transition: opacity 0.15s;
  pointer-events: none;
}
@media (hover: hover) {
  .sc-cover-picker__item:hover:not(.is-active)::after {
    opacity: 1;
  }
}
.sc-cover-picker__item.is-active {
  outline: 1px solid var(--sc-ui-accent, #2f80ed);
  outline-offset: 1px;
}
/* Upload Tab */
.sc-cover-picker__upload {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 32px 0;
}
.sc-cover-picker__upload-hint {
  font-size: 13px;
  color: var(--sc-ui-text-tertiary, #999);
  margin: 0;
}
.sc-cover-picker__upload-btn {
  padding: 8px 20px;
  font-size: 13px;
  border: 1px solid var(--sc-ui-accent, #2f80ed);
  background: var(--sc-ui-accent, #2f80ed);
  color: #fff;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}
@media (hover: hover) {
  .sc-cover-picker__upload-btn:hover {
    background: var(--sc-ui-accent-hover, #1f70dd);
  }
}
.sc-cover-picker__upload-btn:active {
  transform: scale(0.97);
}
/* Link Tab */
.sc-cover-picker__link {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px 0;
}
.sc-cover-picker__link-input {
  width: 100%;
  padding: 8px 12px;
  font-size: 13px;
  border: 1px solid var(--sc-ui-border, #e0e0e0);
  border-radius: 6px;
  outline: none;
  transition: border-color 0.15s;
}
.sc-cover-picker__link-input:focus {
  border-color: var(--sc-ui-accent, #2f80ed);
}
.sc-cover-picker__link-submit {
  align-self: flex-start;
  padding: 6px 16px;
  font-size: 13px;
  border: none;
  background: var(--sc-ui-accent, #2f80ed);
  color: #fff;
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.15s;
}
@media (hover: hover) {
  .sc-cover-picker__link-submit:hover:not(:disabled) {
    background: var(--sc-ui-accent-hover, #1f70dd);
  }
}
.sc-cover-picker__link-submit:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.sc-cover-picker__link-hint {
  font-size: 12px;
  color: var(--sc-ui-text-tertiary, #999);
  margin: 0;
}
/* ── Page Icon ── */
.sc-page-icon {
  pointer-events: none;
  user-select: none;
}
.sc-page-icon.sc-page-icon-placeholder {
  pointer-events: auto;
}
.sc-page-icon.with-page-cover {
  margin-top: -40px;
  position: relative;
}
.sc-page-icon.without-page-cover {
  margin-top: var(--sc-page-top-spacing, 60px);
}
.sc-page-icon .sc-page-icon-emoji {
  pointer-events: auto;
  width: 80px;
  height: 80px;
  font-size: 68px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.sc-page-icon .sc-page-icon-emoji.sc-page-icon-clickable {
  cursor: pointer;
  border-radius: 8px;
  transition: background 0.15s;
  border: none;
  background: transparent;
  padding: 0;
  outline: none;
}
@media (hover: hover) {
  .sc-page-icon .sc-page-icon-emoji.sc-page-icon-clickable:hover {
    background: var(--sc-ui-surface-hover, rgba(0, 0, 0, 0.04));
  }
}
/* ── 无 icon 时的 hover 占位区域 ── */
/* hover 标题及其上方区域（.sc-page-top）时显示 */
.sc-page-icon.sc-page-icon-placeholder {
  opacity: 0;
  transition: opacity 0.15s;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 4px;
  width: auto;
  height: auto;
  padding: 6px 0;
  /* 有封面时：placeholder 在封面和标题之间 */
}
.sc-page-icon.sc-page-icon-placeholder.with-page-cover {
  margin-top: 12px;
}
/* hover 顶部区域、或 placeholder 自身、或 focus-within 时显示 */
.sc-page-top:hover .sc-page-icon.sc-page-icon-placeholder,
.sc-page-icon.sc-page-icon-placeholder:focus-within {
  opacity: 1;
}
/* "已有 icon、无 cover"时的 hover 区——只显示"添加封面" */
.sc-page-extra-actions {
  max-width: 860px;
  margin: 0 auto;
  padding: 6px 0;
  opacity: 0;
  transition: opacity 0.15s;
  user-select: none;
}
.sc-page-top:hover .sc-page-extra-actions,
.sc-page-extra-actions:focus-within {
  opacity: 1;
}
/* ── Page Header Actions 按钮 ── */
.sc-page-actions__btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  font-size: 13px;
  color: var(--sc-ui-text-tertiary, #999);
