  max-height: min(60vh, 420px);
  /* 磨砂质感：半透明背景 + 背后模糊 */
  background: color-mix(in srgb, var(--sc-ui-surface, #fff) 72%, transparent);
  backdrop-filter: blur(8px) saturate(140%);
  -webkit-backdrop-filter: blur(8px) saturate(140%);
