  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}
.sc-block-error-fallback__actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.sc-block-error-fallback__details {
  margin-top: 8px;
