  height: var(--wb-datepicker-showtime-cell-height);
  padding-block: 0;
}

.wb-datepicker-confirm-footer {
  display: flex;
  justify-content: flex-end;
  padding-top: var(--wb-datepicker-confirm-footer-offset);
  border-top: 1px solid var(--wb-datepicker-border-color);
  margin-top: var(--wb-datepicker-spacing-2);
}

.wb-datepicker-confirm-footer__btn {
  border: none;
  background: var(--wb-button-primary-bg);
  color: var(--wb-button-primary-fg);
  cursor: pointer;
  font-size: var(--wb-datepicker-font-size);
  font-weight: 600;
  padding: 0 var(--wb-datepicker-btn-padding-x);
  height: var(--wb-datepicker-confirm-btn-height);
  min-width: var(--wb-datepicker-confirm-btn-min-width);
  border-radius: var(--wb-datepicker-radius-hover);
  transition: background-color var(--wb-datepicker-transition-duration) var(--wb-datepicker-transition-easing);
}
.wb-datepicker-confirm-footer__btn:hover:not(:disabled) {
  background: var(--wb-button-primary-bg-hover);
  border-color: var(--wb-button-primary-bg-hover);
}
.wb-datepicker-confirm-footer__btn:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}
/* Foundation Message 视觉层 —— 使用 wb-* token 体系
 *
 * 5 种 tone：success / info / warning / error / loading
 * 位置：Portal 挂到 document.body，视口顶部居中堆叠
 *
 * 所有颜色 / 尺寸通过 --wb-message-* token 控制，支持 light/dark 主题自动切换。
 */
/* ============ 容器（多条 toast 堆叠） ============ */
.wb-message-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: var(--wb-message-z-index);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: var(--wb-message-stack-gap);
  pointer-events: none;
}

/* scoped 容器：挂载到自定义容器内（如设置弹窗），absolute 相对容器顶部定位 */
.wb-message-container--scoped {
  position: absolute;
  top: var(--wb-spacing-5); /* 16px，距容器顶部 */
  left: 50%;
  transform: translateX(-50%);
  width: auto;
  padding-top: 0;
}

/* ============ 单条 toast ============ */
.wb-message {
  display: inline-flex;
  align-items: center;
  box-sizing: border-box;
  min-height: var(--wb-message-min-height);
  max-height: var(--wb-message-max-height);
  margin-top: var(--wb-message-stack-gap);
}
.wb-message:first-child {
  margin-top: 0;
}
.wb-message {
  padding: var(--wb-message-padding-y) var(--wb-message-padding-x);
  width: fit-content;
  background: var(--wb-message-color-bg);
  border-radius: var(--wb-message-border-radius);
  box-shadow: var(--wb-message-shadow);
  color: var(--wb-message-color-text);
  font-family: "PingFang SC", -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: var(--wb-message-font-size);
  font-weight: var(--wb-font-body-weight);
  font-style: normal;
  text-decoration: none;
  line-height: var(--wb-message-line-height);
  pointer-events: all;
  position: relative;
  -webkit-app-region: no-drag;
  animation: wb-message-enter var(--wb-message-enter-duration) var(--wb-message-enter-easing);
  transition: transform var(--wb-message-reposition-duration) ease;
  /* 0.5px 边框 —— 用伪元素 + scale 实现，兼容所有浏览器 */
}
.wb-message::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 200%;
  height: 200%;
  border: var(--wb-message-border);
  border-radius: calc(var(--wb-message-border-radius) * 2);
  transform: scale(0.5);
  transform-origin: 0 0;
  pointer-events: none;
  box-sizing: border-box;
}
.wb-message {
  /* ============ tone 图标颜色 ============ */
}
.wb-message--success .wb-message__icon {
  color: var(--wb-message-success-color-icon);
}
.wb-message--error .wb-message__icon {
  color: var(--wb-message-error-color-icon);
}
.wb-message--info .wb-message__icon {
  color: var(--wb-message-info-color-icon);
}
.wb-message--warning .wb-message__icon {
  color: var(--wb-message-warning-color-icon);
}
.wb-message--loading .wb-message__icon {
  color: var(--wb-message-loading-color-icon);
}
.wb-message {
  /* ============ 子元素 ============ */
}
.wb-message__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--wb-message-icon-size);
  height: var(--wb-message-icon-size);
  flex-shrink: 0;
  margin-right: var(--wb-message-gap);
}
.wb-message__icon svg {
  width: 100%;
  height: 100%;
  color: currentColor;
}
.wb-message__content {
  flex: 1;
  word-break: break-word;
}
.wb-message {
  /* ============ 关闭按钮 ============ */
}
.wb-message__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: var(--wb-message-close-size);
  height: var(--wb-message-close-size);
  padding: var(--wb-message-close-padding);
  margin-left: var(--wb-message-close-gap);
  border: none;
  background: none;
  cursor: pointer;
  color: var(--wb-message-close-color-icon);
  border-radius: var(--wb-message-close-border-radius);
  -webkit-app-region: no-drag;
  transition: background-color var(--wb-message-close-transition-duration) ease, color var(--wb-message-close-transition-duration) ease;
}
.wb-message__close svg {
  width: var(--wb-message-close-icon-size);
  height: var(--wb-message-close-icon-size);
  display: block;
}
.wb-message__close:hover {
  background: var(--wb-message-close-color-bg-hover);
  color: var(--wb-message-close-color-icon-hover);
}
.wb-message__close:active {
  opacity: 0.7;
}
.wb-message {
  /* loading 图标旋转动画 */
}
.wb-message--loading .wb-message__icon svg {
  animation: wb-message-spin var(--wb-message-spin-duration) linear infinite;
  transform-origin: center;
}
.wb-message {
  /* ============ 退场动画 ============ */
  /* 淡出 + 滑下：退场 toast 自己向下位移 + 淡出，不收缩高度。
   * 退场 toast 保留布局占位，等 JS 移除 DOM 后 flex 自然重排，
   * 避免高度塌缩导致后续 toast 向上跳（与位移方向相反）。 */
}
.wb-message--leaving {
  animation: none;
  opacity: 0;
  transform: translateY(var(--wb-message-translate));
  pointer-events: none;
  transition: opacity var(--wb-message-exit-duration) var(--wb-message-exit-easing), transform var(--wb-message-exit-duration) var(--wb-message-exit-easing);
}

/* ============ keyframes ============ */
@keyframes wb-message-enter {
  from {
    opacity: 0;
    transform: translateY(var(--wb-message-translate));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes wb-message-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
/* Foundation Switch —— 用 wb-switch-* 组件专属 token */
.wb-switch {
  display: inline-flex;
  align-items: center;
  gap: var(--wb-switch-gap);
  cursor: pointer;
  user-select: none;
  color: var(--wb-switch-color-text);
  font-size: var(--wb-switch-font-size);
  line-height: var(--wb-switch-line-height);
}

.wb-switch__control {
  display: inline-flex;
  position: relative;
  flex-shrink: 0;
}

/* 隐藏原生 input，但保留 a11y / keyboard */
.wb-switch__input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  opacity: 0;
  cursor: inherit;
}

.wb-switch__track {
  display: inline-flex;
  align-items: center;
  width: var(--wb-switch-track-width);
  height: var(--wb-switch-track-height);
  padding: var(--wb-switch-track-padding);
  border-radius: var(--wb-switch-radius);
  background: var(--wb-switch-track-bg);
  border: 1px solid transparent;
  box-sizing: border-box;
  transition: background var(--wb-switch-duration) var(--wb-switch-easing), border-color var(--wb-switch-duration) var(--wb-switch-easing);
}

.wb-switch__thumb {
  width: var(--wb-switch-thumb-size);
  height: var(--wb-switch-thumb-size);
  border-radius: var(--wb-switch-radius);
  background: var(--wb-switch-thumb-bg);
  box-shadow: var(--wb-switch-thumb-shadow);
  transition: transform var(--wb-switch-duration) var(--wb-switch-easing);
}

/* 选中态：track 变控件选中背景，thumb 右滑 */
.wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-checked);
  border: 1px solid var(--wb-switch-track-border-color-checked);
}
.wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  transform: translateX(var(--wb-switch-thumb-translate));
}

/* hover 态已移除，checked 态不随 hover 变色 */
/* disabled */
.wb-switch:has(.wb-switch__input:disabled) {
  cursor: not-allowed;
}

/* disabled + checked：bg brand-disabled，无边框 */
.wb-switch:has(.wb-switch__input:disabled) .wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-checked-disabled);
  border: 1px solid transparent;
}

/* disabled + unchecked：track 变灰 */
.wb-switch:has(.wb-switch__input:disabled) .wb-switch__input:not(:checked) + .wb-switch__track {
  background: var(--wb-switch-track-bg-disabled);
  border: 1px solid transparent;
}

/* disabled：thumb 统一使用 disabled 色（checked / unchecked 一致） */
.wb-switch:has(.wb-switch__input:disabled) .wb-switch__thumb {
  background: var(--wb-switch-thumb-bg-disabled-unchecked);
}

/* loading：复用 disabled track 色，但不降低整体透明度；整体已通过 disabled 禁用 */
.wb-switch--loading {
  cursor: wait;
}

/* loading 的 disabled 选择器需要覆盖 disabled thumb 的高优先级规则，避免 thumb 盖住 spinner */
.wb-switch--loading:has(.wb-switch__input:disabled) .wb-switch__thumb {
  background: transparent;
  box-shadow: none;
}

.wb-switch--loading .wb-switch__spinner {
  position: relative;
  z-index: 1;
  background: transparent;
}

/* loading + unchecked：显式覆盖 disabled 关闭态 */
.wb-switch--loading:has(.wb-switch__input:disabled) .wb-switch__input:not(:checked) + .wb-switch__track {
  background: var(--wb-switch-track-bg-disabled);
  border-color: transparent;
  opacity: 1;
}

/* loading + checked：显式覆盖 disabled 开启态 */
.wb-switch--loading:has(.wb-switch__input:disabled) .wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-checked-disabled);
  border-color: transparent;
  opacity: 1;
}

.wb-switch__spinner {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: var(--wb-switch-radius);
  border: var(--wb-switch-spinner-border-width) solid var(--wb-switch-track-color-spinner);
  border-top-color: transparent;
  box-sizing: border-box;
  transform-origin: center;
  will-change: transform;
  animation: wb-switch-spin var(--wb-switch-spinner-duration) linear infinite;
}

/* 明确绑定 loading 状态，避免宿主动画规则覆盖 spinner 的旋转 */
.wb-switch--loading .wb-switch__spinner {
  animation-name: wb-switch-spin;
  animation-duration: var(--wb-switch-spinner-duration);
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-play-state: running;
}

@keyframes wb-switch-spin {
  to {
    transform: rotate(360deg);
  }
}
/* 危险型：checked 态使用 error 色系 */
.wb-switch--danger .wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-danger);
  border: 1px solid var(--wb-switch-track-border-color-danger);
}

/* 危险型 disabled：track 变 error-disabled 色 */
.wb-switch--danger:has(.wb-switch__input:disabled) .wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-danger-disabled);
  border: 1px solid transparent;
}

/* 小尺寸 */
.wb-switch--small {
  font-size: var(--wb-switch-font-size-small);
  line-height: var(--wb-switch-line-height-small);
}
.wb-switch--small .wb-switch__track {
  width: var(--wb-switch-track-width-small);
  height: var(--wb-switch-track-height-small);
}
.wb-switch--small .wb-switch__thumb {
  width: var(--wb-switch-thumb-size-small);
  height: var(--wb-switch-thumb-size-small);
}
.wb-switch--small .wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  transform: translateX(var(--wb-switch-thumb-translate-small));
}

/* 大尺寸（large：34×20）*/
.wb-switch--large .wb-switch__track {
  width: var(--wb-switch-track-width-large);
  height: var(--wb-switch-track-height-large);
}
.wb-switch--large .wb-switch__thumb {
  width: var(--wb-switch-thumb-size-large);
  height: var(--wb-switch-thumb-size-large);
}
.wb-switch--large .wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  transform: translateX(var(--wb-switch-thumb-translate-large));
}

.wb-switch__label {
  display: inline-block;
}
/* =============================================
 * Foundation Tabs
 *
 * InkBar 思路：全局一根 bar，JS 测量 label 几何，
 * 通过 CSS 变量 --wb-tabs-ink-left / --wb-tabs-ink-width 驱动滑动。
 * 首次挂载不启动动画（防飞入），measure 后下一帧开 transition。
 * ============================================= */
/* ---- 容器 ---- */
.wb-tabs {
  display: flex;
  flex-direction: column;
  gap: var(--wb-tabs-panel-gap);
  color: var(--wb-color-text-primary);
  width: 100%;
  min-width: 0;
  overflow: hidden;
  box-sizing: border-box;
}

/* =============================================
 * 垂直模式（tabPosition='left'）
 *
 * 设计稿暂无 left 形态视觉规范，保留原有实现不变。
 * 新增的 type / size / overflow-scroll 均不在此模式生效。
 * ============================================= */
.wb-tabs--left {
  flex-direction: row;
  gap: var(--wb-tabs-vertical-panel-gap);
  align-items: stretch;
}
.wb-tabs--left .wb-tabs__list {
  flex-direction: column;
  align-items: stretch;
  flex-shrink: 0;
  gap: 0;
  border-right: 1px solid var(--wb-tabs-vertical-divider-color-bg);
}
.wb-tabs--left .wb-tabs__tab {
  justify-content: flex-start;
  height: auto;
  min-height: var(--wb-tabs-vertical-default-min-height);
  padding: var(--wb-tabs-vertical-default-padding-x) var(--wb-tabs-vertical-default-padding-y);
  width: 100%;
  font-size: 12px;
  line-height: 16px;
}
.wb-tabs--left .wb-tabs__panel {
  flex: 1 1 0;
  min-width: 0;
}
.wb-tabs--left {
  /* ink-bar 改为竖向，贴右边 */
}
.wb-tabs--left .wb-tabs__ink-bar {
  top: 0;
  bottom: auto;
  left: auto;
  right: -1px;
  width: var(--wb-tabs-vertical-default-inkbar-height);
  min-width: 0;
  min-height: 16px;
  height: var(--wb-tabs-ink-width);
  transform: translateY(var(--wb-tabs-ink-left));
}

/* ---- tab 列表 ---- */
.wb-tabs__list {
  display: inline-flex;
  flex-shrink: 0;
  align-items: stretch;
  gap: var(--wb-tabs-default-tab-gap);
  /* ink-bar 定位容器 */
  position: relative;
  --wb-tabs-ink-left: 0px;
  --wb-tabs-ink-width: 0px;
}

/* ---- 单个 tab 按钮 ---- */
.wb-tabs__tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  /* Button UA 样式会额外引入 1px/6px padding，破坏 Tabs 设计尺寸。 */
  padding: 0;
  cursor: pointer;
  color: var(--wb-tabs-default-color-text);
  font-size: var(--wb-tabs-font-size);
  line-height: var(--wb-tabs-line-height);
  font-weight: 400;
  height: var(--wb-tabs-height);
  white-space: nowrap;
  box-sizing: border-box;
  transition: color var(--wb-tabs-motion-duration) var(--wb-tabs-motion-easing);
  outline: none;
}

/* 选中态加粗不跳变：通过 ::after 伪元素用 bold 文字撑位 */
.wb-tabs__tab-label {
  display: inline-block;
}
.wb-tabs__tab-label::after {
  content: attr(data-text);
  display: block;
  height: 0;
  overflow: hidden;
  visibility: hidden;
  font-weight: 600;
}

.wb-tabs__tab:hover:not(.wb-tabs__tab--active):not(.wb-tabs__tab--disabled) {
  color: var(--wb-tabs-default-color-text-hover);
}

.wb-tabs__tab--active {
  color: var(--wb-tabs-default-color-text-active);
  font-weight: 600;
}

.wb-tabs__tab--disabled {
  color: var(--wb-tabs-default-color-text-disabled);
  cursor: not-allowed;
}

/* ---- InkBar 激活指示线 ---- */
.wb-tabs__ink-bar {
  position: absolute;
  bottom: 0;
  left: 0;
  height: var(--wb-tabs-default-inkbar-height);
  min-width: 16px;
  width: var(--wb-tabs-ink-width);
  background: var(--wb-tabs-inkbar-color-bg);
  border-radius: 0;
  pointer-events: none;
  transform: translateX(var(--wb-tabs-ink-left));
  /* 首次不播放动画，measure 后打开 */
  transition: none;
}

.wb-tabs__list--measured .wb-tabs__ink-bar {
  transition: transform var(--wb-tabs-inkbar-duration) var(--wb-tabs-inkbar-easing), width var(--wb-tabs-inkbar-duration) var(--wb-tabs-inkbar-easing), height var(--wb-tabs-inkbar-duration) var(--wb-tabs-inkbar-easing), background var(--wb-tabs-inkbar-duration) var(--wb-tabs-inkbar-easing);
}

/* =============================================
 * 水平模式（tabPosition='top'）
 *
 * 以下所有功能仅水平 tabs 生效：
 * - 溢出滚动 + 箭头按钮 + addon
 * - 尺寸变体（s / m / l / xl）
 * - 类型变体（default / text / button）
 *
 * 垂直模式不受影响。
 * ============================================= */
/* ---- 溢出滚动 & addon ---- */
.wb-tabs--top .wb-tabs__header {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  min-width: 0;
  overflow: hidden;
}
.wb-tabs--top .wb-tabs__nav {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  flex: 1 1 0;
  min-width: 0;
}
.wb-tabs--top {
  /* 滚动区域：隐藏原生滚动条，占满 nav 宽度 */
}
.wb-tabs--top .wb-tabs__nav-scroll {
  display: flex;
  align-items: center;
  width: 100%;
  box-sizing: border-box;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.wb-tabs--top .wb-tabs__nav-scroll::-webkit-scrollbar {
  display: none;
}
.wb-tabs--top {
  /* 滚动箭头按钮（绝对定位，出现/消失不影响布局宽度） */
}
.wb-tabs--top .wb-tabs__nav-btn {
  position: absolute;
  top: 0;
  bottom: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  pointer-events: none;
}
.wb-tabs--top .wb-tabs__nav-btn-trigger {
  display: flex;
  flex-flow: column;
  justify-content: center;
  align-items: center;
  width: var(--wb-tabs-arrow-btn-width);
  height: var(--wb-tabs-arrow-btn-height);
  border: none;
  color: var(--wb-tabs-arrow-btn-color-text);
  background: var(--wb-tabs-arrow-btn-color-bg);
  transition: color var(--wb-tabs-motion-duration) var(--wb-tabs-motion-easing);
  border-radius: 50%;
  box-shadow: var(--wb-tabs-arrow-btn-color-shadow);
  cursor: pointer;
  pointer-events: auto;
}
.wb-tabs--top .wb-tabs__nav-btn-trigger:hover {
  color: var(--wb-tabs-arrow-btn-color-text-hover);
}
.wb-tabs--top .wb-tabs__nav-btn-trigger svg {
  display: block;
  width: 1em;
  height: 1em;
  font-size: var(--wb-tabs-arrow-btn-icon-size);
  color: inherit;
}
.wb-tabs--top .wb-tabs__nav-btn--left {
  left: 0;
  padding-left: var(--wb-tabs-arrow-btn-shadow-gap);
  padding-right: var(--wb-tabs-arrow-btn-mask-width);
  background: var(--wb-tabs-arrow-btn-color-mask-left);
}
.wb-tabs--top .wb-tabs__nav-btn--right {
  right: 0;
  padding-right: var(--wb-tabs-arrow-btn-shadow-gap);
  padding-left: var(--wb-tabs-arrow-btn-mask-width);
  background: var(--wb-tabs-arrow-btn-color-mask-right);
}
.wb-tabs--top {
  /* addon 固定宽度，不参与滚动 */
}
.wb-tabs--top .wb-tabs__addon {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  flex-grow: 0;
  margin-left: var(--wb-tabs-addon-gap);
}
.wb-tabs--top {
  /* ---- 尺寸变体 ---- */
}
.wb-tabs--top.wb-tabs--s .wb-tabs__tab {
  height: var(--wb-tabs-height-s);
  line-height: var(--wb-tabs-line-height-s);
  font-size: var(--wb-tabs-font-size-s);
}
.wb-tabs--top.wb-tabs--l .wb-tabs__tab {
  height: var(--wb-tabs-height-l);
  line-height: var(--wb-tabs-line-height-l);
  font-size: var(--wb-tabs-font-size-l);
}
.wb-tabs--top.wb-tabs--xl .wb-tabs__tab {
  height: var(--wb-tabs-height-xl);
  line-height: var(--wb-tabs-line-height-xl);
