  display: block;
}

/* =============================================
 * 面板切换动画（仅 destroyOnHide=false + 水平模式 + panelAnimation=true）
 *
 * CSS Grid 同 cell 重叠所有 panel，容器自动撑到最高 panel 高度（接受留白换零跳变）。
 * translateX 滑出/滑入，仅动 transform + opacity 不触发重排。
 * 方向：forward = 旧面板左滑出 + 新面板右进；backward = 反向。
 * ============================================= */
.wb-tabs--top .wb-tabs__panel-wrapper {
  display: grid;
  grid-template-areas: "stack";
  position: relative;
  overflow: hidden;
}

.wb-tabs--top .wb-tabs__panel-wrapper .wb-tabs__panel {
  grid-area: stack;
  /* 覆盖全局 display:none，wrapper 内所有 panel 始终参与布局 */
  display: block;
  opacity: 0;
  pointer-events: none;
}

.wb-tabs--top .wb-tabs__panel-wrapper .wb-tabs__panel--active {
  opacity: 1;
  pointer-events: auto;
}

/* 进入：从对侧滑入 */
.wb-tabs--top .wb-tabs__panel--enter-forward {
  animation: wb-tabs-enter-forward var(--wb-tabs-panel-duration) var(--wb-tabs-panel-easing) both;
}

.wb-tabs--top .wb-tabs__panel--enter-backward {
  animation: wb-tabs-enter-backward var(--wb-tabs-panel-duration) var(--wb-tabs-panel-easing) both;
}

/* 退出：向另一侧滑出 */
.wb-tabs--top .wb-tabs__panel--exit-forward {
  animation: wb-tabs-exit-forward var(--wb-tabs-panel-duration) var(--wb-tabs-panel-easing) both;
}

.wb-tabs--top .wb-tabs__panel--exit-backward {
  animation: wb-tabs-exit-backward var(--wb-tabs-panel-duration) var(--wb-tabs-panel-easing) both;
}

/* forward：旧面板向左滑出，新面板从右侧滑入 */
@keyframes wb-tabs-enter-forward {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}
@keyframes wb-tabs-exit-forward {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-100%);
    opacity: 0;
  }
}
/* backward：旧面板向右滑出，新面板从左侧滑入 */
@keyframes wb-tabs-enter-backward {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}
@keyframes wb-tabs-exit-backward {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(100%);
    opacity: 0;
  }
}
/* 无障碍降级 */
@media (prefers-reduced-motion: reduce) {
  .wb-tabs--top .wb-tabs__panel--enter-forward,
  .wb-tabs--top .wb-tabs__panel--enter-backward,
  .wb-tabs--top .wb-tabs__panel--exit-forward,
  .wb-tabs--top .wb-tabs__panel--exit-backward {
    animation: none;
  }
}
