.overview-team-item__avatar--fallback {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--wb-bg-secondary);
  color: var(--wb-color-text-secondary);
  font-size: 11px;
  font-weight: 600;
}

.overview-team-item__content {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  font-size: 14px;
