/* 层级缩进，h1 = 0，每级 +12px */
.sc-toc__item[data-level='1'] {
  padding-left: 12px;
}
.sc-toc__item[data-level='2'] {
  padding-left: 24px;
}
.sc-toc__item[data-level='3'] {
  padding-left: 36px;
}
.sc-toc__item[data-level='4'] {
  padding-left: 48px;
}
.sc-toc__item[data-level='5'] {
  padding-left: 60px;
}
.sc-toc__item[data-level='6'] {
