/* Buddy 应用切换全屏 loading —— 对齐 Ardot 903:10126
 * 动效对齐弹窗蒙层：overlay fade + 内容「收起再弹出」 */
.industry-switch-loading {
  position: fixed;
  inset: 0;
  /* 与 INDUSTRY_SWITCH_LOADING_Z_INDEX 保持一致；切换器 elevated 层须更高 */
  z-index: 100000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(96px);
  -webkit-backdrop-filter: blur(96px);
  pointer-events: all;
}
[data-theme="dark"] .industry-switch-loading,
body.dark .industry-switch-loading,
.dark .industry-switch-loading {
  background: rgba(0, 0, 0, 0.1);
}
/* 入场：蒙层淡入（同 wb-modal-overlay-in） */
.industry-switch-loading--enter {
  animation: industry-switch-loading-overlay-in var(--wb-motion-duration-base, 200ms) var(--wb-motion-easing-standard, cubic-bezier(0.4, 0, 0.2, 1)) both;
}
.industry-switch-loading--enter .industry-switch-loading__content {
  /* 收起再弹出：先缩小淡入，过冲后落回 1 */
  animation: industry-switch-loading-content-in 320ms var(--wb-motion-easing-emphasized, cubic-bezier(0.2, 0, 0, 1)) both;
}
/* 离场：内容收起 + 蒙层淡出 */
.industry-switch-loading--leave {
  animation: industry-switch-loading-overlay-out var(--wb-motion-duration-base, 200ms) var(--wb-motion-easing-standard, cubic-bezier(0.4, 0, 0.2, 1)) both;
}
.industry-switch-loading--leave .industry-switch-loading__content {
  animation: industry-switch-loading-content-out var(--wb-motion-duration-base, 200ms) var(--wb-motion-easing-emphasized, cubic-bezier(0.2, 0, 0, 1)) both;
}
.industry-switch-loading__content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  transform-origin: center center;
  will-change: transform, opacity;
}
.industry-switch-loading__icon {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  border-radius: 50%;
  border: 1.6px solid #fff;
  box-shadow: 0 0 3.2px rgba(0, 0, 0, 0.08);
  background: #e4e4e4;
  overflow: hidden;
  box-sizing: border-box;
}
.industry-switch-loading__icon img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}
.industry-switch-loading__icon-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(0, 0, 0, 0.45);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  user-select: none;
}
.industry-switch-loading__label {
  margin: 0;
  color: rgba(0, 0, 0, 0.5);
  font-family: "SF Pro Text", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 24px;
  white-space: nowrap;
}
[data-theme="dark"] .industry-switch-loading__label,
body.dark .industry-switch-loading__label,
.dark .industry-switch-loading__label {
  color: rgba(255, 255, 255, 0.5);
}
[data-theme="dark"] .industry-switch-loading__icon-fallback,
body.dark .industry-switch-loading__icon-fallback,
.dark .industry-switch-loading__icon-fallback {
  color: rgba(255, 255, 255, 0.45);
}
@keyframes industry-switch-loading-overlay-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes industry-switch-loading-overlay-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
/* 收起再弹出：起点收起 → 过冲弹出 → 回落定格 */
@keyframes industry-switch-loading-content-in {
  0% {
    opacity: 0;
    transform: scale(0.86);
  }
  55% {
    opacity: 1;
    transform: scale(1.04);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes industry-switch-loading-content-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.86);
  }
}
