 * 仅作用在 wrapClassName 为本类的 Modal overlay 上。
 */
.claw-delete-assistant-overlay {
  background: transparent;
  backdrop-filter: none;
}
.claw-sidebar-drawer {
  display: flex;
  flex: 0 0 264px;
  width: 264px;
  height: 100%;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  color: var(--wb-color-text-primary);
  background: var(--wb-color-bg-secondary-hover-active);
  border-right: 1px solid var(--wb-color-border-secondary);
}
.claw-sidebar-drawer--floating {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 9999;
  box-shadow: var(--wb-shadow-xl, 0 4px 16px var(--wb-shadow-color));
  animation: claw-sidebar-drawer-in 150ms ease-out;
}
.claw-sidebar-drawer__titlebar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex: 0 0 56px;
  height: 56px;
  padding: 0 var(--wb-spacing-4) 0 var(--wb-spacing-7);
  -webkit-app-region: drag;
}
.claw-sidebar-drawer__titlebar--mac-offset {
  padding-left: 90px;
}
.claw-sidebar-drawer__title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  font-size: 16px;
  font-weight: 700;
  line-height: 21px;
  color: var(--wb-color-text-primary);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.claw-sidebar-drawer__title-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: var(--wb-spacing-1);
  -webkit-app-region: no-drag;
}
.claw-sidebar-drawer__menu {
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--wb-spacing-1);
  padding: 0 0 var(--wb-spacing-4);
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--wb-color-text-tertiary) 34%, transparent) transparent;
}
.claw-sidebar-drawer__primary-tabs {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  gap: var(--wb-spacing-1);
}
.claw-sidebar-drawer__normal-tabs,
.claw-sidebar-drawer__enterprise-tabs {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
}
.claw-sidebar-drawer__section-header {
  display: flex;
  align-items: center;
  padding: 6px 0 6px 16px;
  margin: 0 12px;
  height: 36px;
  flex: 0 0 36px;
  gap: 6px;
}
.claw-sidebar-drawer__section-header--clickable {
  border: none;
  background: transparent;
  color: inherit;
  cursor: pointer;
  border-radius: var(--wb-radius-sm);
  transition: background 0.15s;
  text-align: left;
}
.claw-sidebar-drawer__section-header--clickable:hover {
  background: var(--wb-color-bg-tertiary-hover);
}
.claw-sidebar-drawer__section-body {
  display: flex;
  flex-direction: column;
  gap: var(--wb-spacing-1);
  overflow: hidden;
}
.claw-sidebar-drawer__section-body--collapsed {
  height: 0;
  overflow: hidden;
  gap: 0;
}
.claw-sidebar-drawer__section-chevron {
  flex: 0 0 14px;
  color: var(--wb-color-text-tertiary);
  transition: transform 0.2s ease;
}
.claw-sidebar-drawer__section-chevron--collapsed {
  transform: rotate(-90deg);
}
.claw-sidebar-drawer__section-title {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  line-height: 16px;
  color: var(--wb-color-text-tertiary);
  white-space: nowrap;
}
.claw-sidebar-drawer__create-btn {
  display: flex;
  margin-left: auto;
  flex: 0 0 28px;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 24px;
  margin-right: 6px;
  padding: 0;
  border: none;
  border-radius: var(--wb-radius-sm);
  background: transparent;
  color: var(--wb-color-text-tertiary);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.claw-sidebar-drawer__create-btn:hover {
  background: var(--wb-color-bg-tertiary-hover);
  color: var(--wb-color-text-primary);
}
.claw-sidebar-drawer__create-btn:active {
  background: var(--wb-color-bg-tertiary-active);
}
.claw-sidebar-drawer__create-entry {
  flex: 0 0 auto;
  padding-top: var(--wb-spacing-1);
}
.claw-sidebar-drawer__divider {
  flex: 0 0 auto;
  height: 1px;
  margin: 8px 12px;
  background: var(--wb-color-border-secondary);
}
@keyframes claw-sidebar-drawer-in {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
