  padding: 0 12px;
}
.claw-assistant-list-skeleton__avatar,
.claw-assistant-list-skeleton__line {
  background: var(--wb-bg-tertiary);
}
.claw-assistant-list-skeleton__avatar {
  width: 32px;
  height: 32px;
  border-radius: var(--wb-radius-lg);
}
.claw-assistant-list-skeleton__line {
  width: 96px;
  height: 12px;
  border-radius: var(--wb-radius-sm);
}
.claw-empty-tab-pane {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  background: var(--wb-bg-primary);
  color: var(--wb-color-text-primary);
}
.claw-empty-tab-pane__topbar {
  display: flex;
  align-items: center;
  flex: 0 0 56px;
  height: 56px;
  padding: 0 12px;
}
.claw-empty-tab-pane__content {
  display: flex;
  flex: 1;
  min-height: 0;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 24px;
  text-align: center;
}
.claw-empty-tab-pane__title {
  font-size: 16px;
  font-weight: 600;
}
.claw-empty-tab-pane__hint {
  font-size: 13px;
  color: var(--wb-color-text-secondary);
}
.claw-empty-tab-pane__actions {
  display: flex;
  gap: 8px;
