  padding-top: 8px;
}
.claw-assistant-chat-skeleton {
  overflow: hidden;
}
.claw-assistant-chat-skeleton__content {
  display: flex;
  flex: 1;
  min-height: 0;
  flex-direction: column;
  gap: 24px;
  padding: 32px 64px;
}
.claw-assistant-chat-skeleton__message {
  display: flex;
  max-width: 680px;
  gap: 12px;
}
.claw-assistant-chat-skeleton__message--user {
  align-self: flex-end;
  flex-direction: row-reverse;
}
.claw-assistant-chat-skeleton__message--assistant {
  align-self: flex-start;
}
.claw-assistant-chat-skeleton__avatar,
.claw-assistant-chat-skeleton__line {
  background: linear-gradient(90deg, color-mix(in srgb, var(--wb-border-default) 70%, transparent) 25%, color-mix(in srgb, var(--wb-bg-hover) 85%, transparent) 50%, color-mix(in srgb, var(--wb-border-default) 70%, transparent) 75%);
  background-size: 200% 100%;
  animation: claw-assistant-chat-skeleton-shimmer 1.5s ease-in-out infinite;
}
.claw-assistant-chat-skeleton__avatar {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
