  animation-delay: 0.4s;
}
@keyframes lexiang-auth-arrow-flow {
  0% {
    opacity: 0.25;
    transform: translateX(-2px);
    color: var(--wb-color-text-placeholder);
  }
  40% {
    opacity: 1;
    transform: translateX(0);
    color: var(--wb-brand-bright);
  }
  70% {
    opacity: 0.5;
    transform: translateX(1px);
    color: var(--wb-brand-soft);
  }
  100% {
    opacity: 0.25;
    transform: translateX(-2px);
    color: var(--wb-color-text-placeholder);
  }
}
/* ---- 标题 ---- */
.lexiang-auth-guide__title {
  margin: 4px 0 0;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--wb-text-strong, #111);
}
/* ---- 描述文案 ---- */
.lexiang-auth-guide__desc {
  margin: 0;
  font-size: 13px;
  line-height: 1.7;
  color: var(--wb-text-medium, #6b6d7b);
  max-width: 440px;
}
.lexiang-auth-guide__desc strong {
  color: inherit;
  font-weight: inherit;
}
/* ---- 权限卡片 ---- */
.lexiang-auth-guide__permissions {
  width: 100%;
  padding: 20px 24px;
  border-radius: 6px;
  background: var(--wb-bg-secondary, #f7f8fa);
  border: none;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.lexiang-auth-guide__permissions-title {
  font-size: 13px;
  font-weight: 400;
  color: var(--wb-text-weak, #8b8d98);
  line-height: 1.4;
}
.lexiang-auth-guide__permissions-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.lexiang-auth-guide__permission-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}
.lexiang-auth-guide__permission-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--wb-text-strong);
  margin-top: 2px;
}
.lexiang-auth-guide__permission-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.lexiang-auth-guide__permission-label {
  font-size: 13px;
  font-weight: 400;
  color: var(--wb-text-strong, #111);
  line-height: 1.4;
}
.lexiang-auth-guide__permission-desc {
  font-size: 12px;
  color: var(--wb-text-weak, #8b8d98);
  line-height: 1.5;
}
/* ---- 错误提示（对齐 tencent-docs-auth-guide__error / ima-auth-guide__error） ---- */
.lexiang-auth-guide__error {
  padding: 8px 12px;
  border-radius: 6px;
  background: var(--wb-bg-error-subtle);
  color: var(--wb-status-error);
  font-size: 12px;
  line-height: 1.4;
  width: 100%;
  box-sizing: border-box;
}
/* ---- 主行动按钮（乐享黑色主按钮） ---- */
.lexiang-auth-guide__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 12px 24px;
  border-radius: 6px;
  border: none;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  background: var(--wb-kb-btn-primary-bg, #1a1a1a);
  color: var(--wb-kb-btn-primary-fg);
  transition: background 0.15s ease, box-shadow 0.15s ease, transform 0.08s ease;
}
.lexiang-auth-guide__btn:hover:not(:disabled) {
  background: var(--wb-kb-btn-primary-bg-hover, #000000);
}
.lexiang-auth-guide__btn:active:not(:disabled) {
  background: var(--wb-kb-btn-primary-bg-hover, #000000);
}
.lexiang-auth-guide__btn:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}
.lexiang-auth-guide__btn-label {
  line-height: 1;
}
.lexiang-auth-guide__btn--loading {
  opacity: 0.75;
}
.lexiang-auth-guide__btn--loading:hover:not(:disabled) {
  background: var(--wb-kb-btn-primary-bg);
}
/* ---- 底部隐私提示 ---- */
.lexiang-auth-guide__footer {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--wb-text-weak, #8b8d98);
  line-height: 1.4;
  margin-top: 4px;
}
.lexiang-auth-guide__footer svg {
  color: var(--wb-brand-bright);
  flex-shrink: 0;
}
.lexiang-auth-guide__spinner {
  display: inline-block;
  width: 14px;
  height: 14px;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: lexiang-auth-spin 0.6s linear infinite;
}
@keyframes lexiang-auth-spin {
  to {
    transform: rotate(360deg);
  }
}
.lexiang-auth-webview-container {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
}
.lexiang-auth-webview {
  width: 100%;
  height: 100%;
  min-height: 530px;
  border: none;
}
/* Dark Mode */
.dark .lexiang-auth-guide__title {
  color: var(--wb-text-strong, #d2d3e0);
}
.dark .lexiang-auth-guide__permissions {
  background: var(--wb-bg-secondary, #25262b);
}
.dark .lexiang-auth-guide__permission-icon {
  color: var(--wb-text-strong);
}
.dark .lexiang-auth-guide__permission-label {
  color: var(--wb-text-strong, #d2d3e0);
}
/* LexiangAuthPage 样式（webview 方案） */
.lexiang-auth-page {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}
.lexiang-auth-page__webview-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.lexiang-auth-page__webview-container webview {
  flex: 1;
  width: 100%;
  height: 100%;
  border: none;
  min-height: 0;
}
.lexiang-auth-page__loading-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: var(--wb-bg-secondary);
  z-index: 1;
}
.lexiang-auth-page__spinner {
  width: 32px;
  height: 32px;
  border: 3px solid #e2e2e2;
  border-top-color: var(--wb-brand-bright);
  border-radius: 50%;
  animation: lexiang-auth-spin 0.8s linear infinite;
}
@keyframes lexiang-auth-spin {
  to {
    transform: rotate(360deg);
  }
}
.lexiang-auth-page__status-pane {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 32px;
  text-align: center;
}
.lexiang-auth-page__status-icon {
  width: 48px;
  height: 48px;
}
.lexiang-auth-page__status-icon[data-variant='warning'] {
  color: #f59e0b;
}
.lexiang-auth-page__status-icon[data-variant='error'] {
  color: #ef4444;
}
.lexiang-auth-page__status-icon[data-variant='success'] {
  color: var(--wb-brand-bright);
}
.lexiang-auth-page__status-icon svg {
  width: 100%;
  height: 100%;
}
.lexiang-auth-page__status-title {
  font-size: 15px;
  font-weight: 500;
  color: var(--wb-text-strong);
  line-height: 1.4;
}
.lexiang-auth-page__status-desc {
  font-size: 13px;
  color: var(--wb-text-medium, #888);
  line-height: 1.5;
  max-width: 360px;
}
.lexiang-auth-page__actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 4px;
}
.lexiang-auth-page__primary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 99px;
  height: 36px;
  min-width: 88px;
  padding: 0 20px;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  outline: none;
  background-color: var(--wb-brand-bright);
  color: var(--wb-text-white);
  transition: background-color 120ms ease;
}
.lexiang-auth-page__primary-btn:hover {
  background-color: var(--wb-kb-brand-hover);
}
.lexiang-auth-page__secondary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--wb-border-default);
  border-radius: 99px;
  height: 36px;
  min-width: 88px;
  padding: 0 20px;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  outline: none;
  background-color: var(--wb-bg-primary);
  color: var(--wb-text-strong);
  transition: background-color 120ms ease, border-color 120ms ease;
}
.lexiang-auth-page__secondary-btn:hover {
  background-color: var(--wb-bg-card-strong);
  border-color: var(--wb-border-default);
}
.lexiang-auth-page__link-btn {
  background: transparent;
  border: none;
  color: var(--wb-text-medium, #888);
  font-size: 12px;
  cursor: pointer;
  padding: 0;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.lexiang-auth-page__link-btn:hover {
  color: var(--wb-text-strong, #222);
}
.lexiang-auth-page__bottom-bar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 8px 16px;
  border-top: 1px solid var(--wb-border-default);
  background: var(--wb-bg-hover);
}
/* Dark Mode */
.dark .lexiang-auth-page__loading-overlay {
  background: var(--wb-bg-primary);
}
.dark .lexiang-auth-page__spinner {
  border-color: var(--wb-border-strong);
  border-top-color: var(--wb-brand-bright);
}
.dark .lexiang-auth-page__status-title {
  color: var(--wb-text-strong);
}
.dark .lexiang-auth-page__bottom-bar {
  background: var(--wb-bg-secondary);
  border-top-color: var(--wb-border-strong);
}
.dark .lexiang-auth-page__secondary-btn {
  background-color: var(--wb-bg-elevated);
  color: var(--wb-text-strong);
  border-color: var(--wb-border-default);
}
.dark .lexiang-auth-page__secondary-btn:hover {
  background-color: var(--wb-bg-hover);
  border-color: var(--wb-border-default);
}
.dark .lexiang-auth-page__link-btn {
  color: var(--wb-text-muted, #858699);
}
.dark .lexiang-auth-page__link-btn:hover {
  color: var(--wb-text-strong, #d2d3e0);
}
/**
 * WorkBuddyTopBar styles
 */
.workbuddy-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
  min-height: 56px;
  flex-shrink: 0;
  padding: 0 12px 0 16px;
  box-sizing: border-box;
  -webkit-app-region: drag;
  position: sticky;
  top: 0;
  width: 100%;
  z-index: 101;
  transition: margin-top 180ms cubic-bezier(0.05, 0.7, 0.1, 1);
  gap: 8px;
}
@media (max-height: 400px) {
  .workbuddy-topbar {
    height: 40px;
    min-height: 40px;
    padding: 0 8px 0 12px;
  }
