}
.workbuddy-topbar .workbuddy-topbar-title {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  -webkit-app-region: no-drag;
}
.workbuddy-topbar .workbuddy-topbar-options {
  width: 100%;
