.workbuddy-topbar.workbuddy-topbar--collapsed.workbuddy-topbar--mac:has(.workbuddy-topbar-title--mac-offset) .workbuddy-topbar-left,
.workbuddy-topbar.workbuddy-topbar--collapsed.workbuddy-topbar--mac:has(.workbuddy-topbar-title--mac-offset) .ec-topbar__left {
  margin-left: 0;
}
.workbuddy-topbar .workbuddy-topbar-actions {
