  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  -webkit-app-region: no-drag;
}
.workbuddy-topbar .workbuddy-topbar-actions .wb-button--icon-only {
  color: var(--wb-color-text-secondary);
}
.workbuddy-topbar .workbuddy-topbar-actions .wb-button--icon-only:hover:not(:disabled) {
  color: var(--wb-color-text-primary);
}
.workbuddy-topbar .workbuddy-topbar-logo {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  text-decoration: none;
  flex-shrink: 0;
}
.workbuddy-topbar .workbuddy-topbar-logo:hover {
  opacity: 0.8;
}
.workbuddy-topbar .workbuddy-topbar-logo img {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}
.workbuddy-topbar .workbuddy-topbar-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--wb-color-text-solid);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 24px;
  height: 24px;
  display: inline-block;
  vertical-align: middle;
}
.workbuddy-topbar .workbuddy-topbar-title--workspace {
  display: flex;
  align-items: center;
  height: 32px;
  line-height: normal;
  vertical-align: initial;
}
.workbuddy-topbar .workbuddy-topbar-title--mac-offset {
  padding-left: 75px;
}
.workbuddy-topbar .workbuddy-topbar-title--workspace:has(.claw-workspace-title--peeking) {
  width: 264px;
  max-width: 264px;
}
.workbuddy-topbar .workbuddy-topbar-breadcrumb {
  display: inline-flex;
  align-items: center;
  line-height: 24px;
  height: 24px;
  vertical-align: middle;
  max-width: 100%;
  min-width: 0;
  overflow: hidden;
}
.workbuddy-topbar .workbuddy-topbar-breadcrumb .wb-breadcrumb__item:last-child {
  max-width: 400px;
}
.workbuddy-topbar .workbuddy-topbar-breadcrumb-root {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--wb-color-text-tertiary);
