  line-height: 1;
  font-weight: 400;
}
.workbuddy-topbar .workbuddy-topbar-title-input {
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  background: transparent;
  border: 1px solid var(--wb-border-default);
  border-radius: 4px;
  padding: 2px 6px;
  outline: none;
  min-width: 120px;
  max-width: 300px;
  height: 24px;
  line-height: 24px;
  box-sizing: border-box;
}
.workbuddy-topbar .workbuddy-topbar-title-input:focus {
  border-color: var(--wb-color-border-focus);
}
.workbuddy-topbar .workbuddy-topbar-edit-button {
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  color: var(--wb-color-text-secondary);
  transition: opacity 0.15s ease;
  flex-shrink: 0;
  height: 24px;
  display: none;
}
.workbuddy-topbar .workbuddy-topbar-edit-button:hover {
  color: var(--wb-color-text-primary);
}
.workbuddy-topbar .workbuddy-topbar-edit-button svg {
  width: 14px;
  height: 14px;
}
.workbuddy-topbar .workbuddy-topbar-title-area {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  overflow: hidden;
  gap: 4px;
}
.workbuddy-topbar .workbuddy-topbar-title-area .workbuddy-topbar-title {
  min-width: 0;
  flex-shrink: 1;
}
.workbuddy-topbar .workbuddy-topbar-title-area:hover .workbuddy-topbar-edit-button {
  display: inline-flex;
}
.workbuddy-topbar--scrolled {
  border-bottom: 1px solid var(--wb-color-border-tertiary);
}
body[data-application-name="workbuddy"] .cb-grid--drawer-open .workbuddy-topbar {
