/**
 * Settings Modal 样式
 * 使用 cb-chat-ui 全局变量
 */
.settings-modal-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  z-index: 1000;
  animation: fadeIn var(--wb-motion-duration-fast) var(--wb-motion-easing-standard);
}
.settings-modal-overlay--appearance {
  background: none !important;
}
.settings-modal {
  width: 880px;
  max-width: 92vw;
  height: 720px;
  max-height: 88vh;
  --cb-settings-card-background: color-mix(in srgb, var(--cb-vscode-editor-background, #1e1e1e) 96%, #64748b 4%);
  --cb-settings-card-background-strong: color-mix(in srgb, var(--cb-vscode-editor-background, #1e1e1e) 92%, #64748b 8%);
  --cb-settings-dialog-background: var(--wb-bg-secondary);
  --cb-settings-card-border: var(--wb-color-border-primary);
  background: var(--wb-bg-secondary);
  border: none;
  border-radius: var(--wb-radius-4xl);
  display: flex;
  overflow: hidden;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.24), 0 8px 32px rgba(0, 0, 0, 0.08);
  animation: slideUp var(--wb-motion-duration-base) var(--wb-motion-easing-emphasized);
}
.settings-modal__nav {
  width: 200px;
  flex-shrink: 0;
  display: flex;
  padding: var(--wb-spacing-4);
  flex-direction: column;
  align-items: flex-start;
  gap: var(--wb-spacing-1);
  background: var(--wb-bg-secondary);
  border-right: none;
  user-select: none;
  -webkit-app-region: no-drag;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.settings-modal__nav:hover {
  scrollbar-color: var(--wb-scrollbar-thumb-bg) transparent;
}
.settings-modal__header {
  flex-shrink: 0;
  display: flex;
