.settings-modal__header-left {
  display: flex;
  align-items: center;
  gap: var(--wb-spacing-2);
  min-width: 0;
}
.settings-modal__header-right {
  display: flex;
  align-items: center;
  gap: var(--wb-spacing-3);
  flex-shrink: 0;
}
.settings-modal__header-extra {
  display: flex;
  align-items: center;
  -webkit-app-region: no-drag;
}
.settings-modal__back {
