}
.settings-modal__back.wb-button {
  width: var(--wb-icon-size-lg);
  height: var(--wb-icon-size-lg);
  border-radius: 6px;
}
.settings-modal__back.wb-button .wb-button__icon {
  width: var(--wb-icon-size-lg);
  height: var(--wb-icon-size-lg);
}
.settings-modal__back.wb-button .wb-button__icon svg {
  fill: none;
}
.settings-modal__title {
  color: var(--wb-color-text-primary, rgba(0, 0, 0, 0.9));
