  padding-bottom: 8px;
}
.wb-task-result-recommend .wb-skill-rec-chip {
  height: 28px;
}

.vscode-dark .wb-skill-rec-chip,
.vscode-high-contrast .wb-skill-rec-chip {
  background: rgba(255, 255, 255, 0.06);
  color: #FFFFFF;
}
