  background: transparent;
  color: var(--wb-todo-menu-text-default);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 400;
  text-align: left;
  overflow: hidden;
