}
.conversation-list-tab-button .conversation-list-tab-inline-icon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  display: inline-flex;
  color: var(--wb-todo-menu-icon-default);
  transition: color 0.15s ease;
}
.conversation-list-tab-button .conversation-list-tab-inline-icon svg {
  width: 16px;
  height: 16px;
}
.conversation-list-tab-button > span.conversation-list-tab-button-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
