  margin-left: 4px;
  padding: 0 5px;
  font-size: 10px;
  line-height: 16px;
  font-weight: 500;
  border-radius: 4px;
  border: 1px solid var(--wb-border-default);
  color: var(--wb-todo-menu-text-default);
  opacity: 0.5;
}
.conversation-list-tab-button-box {
  border-radius: 8px;
}
.conversation-list-tab-button-box:hover {
  background: var(--wb-todo-menu-bg-hover);
  color: var(--wb-todo-menu-text-default);
}
.conversation-list-tab-button-box:hover svg,
.conversation-list-tab-button-box:hover .conversation-list-tab-icon {
  color: var(--wb-todo-menu-text-default);
}
.conversation-list-tab-button-box.active {
  background: var(--wb-todo-menu-bg-active);
  color: var(--wb-todo-menu-text-default);
