}
.conversation-list-tab-button-box.active svg,
.conversation-list-tab-button-box.active .conversation-list-tab-icon {
  color: var(--wb-todo-menu-text-default);
}
.conversation-list-tab-row {
  display: flex;
  align-items: center;
  border-radius: 8px;
  transition: background-color 0.15s ease;
}
.conversation-list-tab-row:hover {
  background: var(--wb-todo-menu-bg-hover);
}
.conversation-list-tab-row:hover .conversation-list-tab-button svg {
  color: var(--wb-todo-menu-text-default);
}
.conversation-list-tab-row.active {
  background: var(--wb-todo-menu-bg-active);
