}
.conversation-list-tab-row .conversation-list-tab-button {
  flex: 1;
  min-width: 0;
  background: transparent !important;
}
.conversation-list-tab-actions {
  display: none;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
  padding-right: 4px;
}
.conversation-list-tab-row:hover .conversation-list-tab-actions,
.conversation-list-tab-row.active .conversation-list-tab-actions {
  display: flex;
}
.conversation-list-tab-row:hover .conversation-list-tab-button-sub,
.conversation-list-tab-row.active .conversation-list-tab-button-sub {
  display: none;
}
.conversation-list-tab-group {
  display: flex;
  flex-direction: column;
}
.conversation-list-tab-group-header {
  position: relative;
}
.conversation-list-tab-group-header .conversation-list-tab-group-chevron {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
