}
.conversation-list-tab-child {
  padding-left: 32px !important;
  height: 32px !important;
  font-size: 13px !important;
  line-height: 20px !important;
}
.conversation-list-tab-child svg {
  width: 16px !important;
  height: 16px !important;
}
@keyframes claw-name-fade-out-up {
  0% {
    opacity: 1;
    transform: translateY(0);
  }
  100% {
    opacity: 0;
    transform: translateY(-8px);
  }
}
@keyframes claw-name-fade-in-up {
  0% {
    opacity: 0;
    transform: translateY(8px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}
.claw-name-loading {
  display: inline-block;
  opacity: 0;
}
.claw-name-ready {
  display: inline-block;
}
.claw-name-fade-out {
  display: inline-block;
  animation: claw-name-fade-out-up 0.3s ease-in forwards;
}
.claw-name-fade-in {
