.conversation-item,
.conversation-pinned-item {
  position: relative;
}
.conversation-team-tree {
  position: relative;
  display: grid;
  margin: 4px 0 8px 0;
  padding-left: 0;
  overflow: hidden;
  transition: grid-template-rows 240ms cubic-bezier(0.33, 0, 0.2, 1), opacity 240ms cubic-bezier(0.33, 0, 0.2, 1), margin 240ms cubic-bezier(0.33, 0, 0.2, 1);
}
.conversation-team-tree--collapsed {
  grid-template-rows: 0fr;
  opacity: 0;
  pointer-events: none;
  margin: 0 0 0 34px;
}
.conversation-team-tree--expanded {
  grid-template-rows: 1fr;
  opacity: 1;
  pointer-events: auto;
}
.conversation-team-member-copy {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  padding: 4px 0;
}
.conversation-team-members {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-top: 0;
  min-height: 0;
  overflow: hidden;
}
.workspace-drag-item > .collapsible-section > .collapsible-section-content {
  padding-left: 19px;
}
.conversation-team-member {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-height: 38px;
  padding: 6px 5px;
  border-radius: 4px;
  border: none;
  background: transparent;
  font-size: 11px;
  color: var(--wb-color-text-secondary);
}
.conversation-team-member--compact {
  min-height: 30px;
  padding: 0 12px 0 36px;
  border-radius: 8px;
}
.conversation-team-member-title {
  min-width: 0;
  overflow: hidden;
  color: var(--wb-color-text-primary);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.conversation-team-member-title__name {
  font-weight: 400;
  vertical-align: baseline;
}
.conversation-team-member--compact .conversation-team-member-title {
  font-size: 12px;
  font-weight: 500;
}
.conversation-team-member-title-row {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  flex: 1;
  width: 100%;
  min-width: 0;
  align-items: center;
  column-gap: 2px;
}
.conversation-team-member-title-row--no-index {
