.conversation-team-member-button {
  cursor: pointer;
  text-align: left;
  transition: background-color 0.15s ease;
}
.conversation-team-member-button:hover {
  background: var(--wb-todo-menu-bg-hover);
}
.conversation-team-member-button.conversation-team-member--selected,
.conversation-team-member-button.conversation-team-member--selected:hover {
  background: var(--wb-todo-menu-bg-active);
}
.conversation-team-member-button:focus-visible {
  outline: 1px solid var(--wb-border-focus);
