}
.conversation-team-status-icon-running svg {
  width: 16px;
  height: 16px;
}
@keyframes conversation-team-status-icon-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
.conversation-team-status-dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--wb-color-text-secondary);
  opacity: 0.7;
}
.conversation-section-tasks,
.conversation-section-groups {
  padding-bottom: 4px;
}
.conversation-section-tasks:has(.conversation-section-motion.is-open),
.conversation-section-groups:has(.conversation-section-motion.is-open) {
  padding-bottom: 16px;
}
.conversation-section-label {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;
  padding: 5px 12px;
  cursor: pointer;
  user-select: none;
  border-radius: 8px;
  transition: background-color 0.15s ease, color 0.15s ease;
  position: sticky;
  top: 0;
  z-index: var(--wb-conversation-list-sticky-header-layer);
  background: var(--wb-sidebar-bg, var(--cb-sidebar-bg, var(--vscode-sideBar-background, #fff)));
}
.conversation-section-label::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 1px;
  background: transparent;
  transition: background 0.15s ease;
  pointer-events: none;
}
.conversation-section-label:hover {
  background: linear-gradient(var(--wb-todo-menu-bg-hover), var(--wb-todo-menu-bg-hover)), var(--wb-sidebar-bg, var(--cb-sidebar-bg, var(--vscode-sideBar-background, #fff)));
}
.conversation-section-label:hover .conversation-section-label-text {
  color: var(--wb-todo-menu-text-default);
}
.conversation-section-label:hover .conversation-section-chevron {
  color: var(--wb-todo-menu-text-default);
}
.conversation-section-label:hover .conversation-section-compact-btn {
  opacity: 1;
  visibility: visible;
}
.conversation-section-label:hover .conversation-section-add-btn {
  opacity: 1;
  visibility: visible;
}
.conversation-section-label-text {
  font-size: 12px;
  font-weight: 600;
  line-height: calc(max(8px, calc(12px + var(--cb-font-size-offset) * 1px)) + 8px);
  text-transform: none;
  color: var(--wb-color-text-tertiary);
  letter-spacing: 0;
  transition: color 0.15s ease;
}
.conversation-section-chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  transition: transform 0.2s ease, color 0.15s ease;
  color: var(--wb-todo-menu-text-heading);
}
.conversation-section-chevron svg {
  width: 14px;
  height: 14px;
}
.conversation-section-chevron.conversation-section-chevron-expanded {
  transform: rotate(0deg);
}
.conversation-section-chevron:not(.conversation-section-chevron-expanded) {
  transform: rotate(-90deg);
}
.conversation-section-filter-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  margin-left: auto;
  border-radius: 4px;
  cursor: pointer;
  color: var(--wb-icon-secondary);
  transition: color 0.15s ease, background-color 0.15s ease;
}
.conversation-section-filter-btn svg {
  width: 16px;
  height: 16px;
}
.conversation-section-filter-btn:hover {
  color: var(--wb-color-text-primary);
  background-color: var(--wb-button-ghost-bg-hover);
}
.conversation-section-filter-btn__dot {
  position: absolute;
  top: 1px;
  right: 1px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--wb-accent-unread);
  border: 1px solid var(--wb-bg-primary);
  pointer-events: none;
}
.task-filter-trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  cursor: pointer;
}
.wb-popover.task-filter-popover {
  background: var(--wb-bg-card);
  border: 0.5px solid var(--wb-border-subtle);
  border-radius: 16px;
  box-shadow: var(--wb-shadow-popover);
  padding: 8px;
  width: 240px;
}
.task-filter-menu {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.task-filter-menu__section {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.task-filter-menu__section-title {
  padding: 3px 8px;
  font-size: 12px;
  line-height: 20px;
  color: var(--wb-color-text-tertiary);
  user-select: none;
  display: flex;
  align-items: center;
  gap: 8px;
}
.task-filter-menu__options {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.task-filter-menu__option {
  display: flex;
  align-items: center;
  width: 100%;
  height: 32px;
  padding: 3px 8px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-todo-menu-text-default);
  font-size: 14px;
  line-height: 22px;
  cursor: pointer;
  transition: background-color 0.15s ease;
  text-align: left;
  gap: 8px;
}
.task-filter-menu__option:hover {
  background-color: var(--wb-dropdown-item-bg-hover);
}
.task-filter-menu__option--selected {
  background-color: var(--wb-dropdown-item-bg-selected);
  font-weight: 600;
}
.task-filter-menu__option--selected:hover {
  background-color: var(--wb-dropdown-item-bg-selected);
}
.task-filter-menu__option--selected .task-filter-menu__option-check {
  display: flex;
}
.task-filter-menu__option--disabled {
  color: var(--wb-todo-menu-text-heading);
}
.task-filter-menu__option-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
.task-filter-menu__option-label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.task-filter-menu__option-check {
  display: none;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  color: var(--wb-accent-unread);
}
.task-filter-menu__divider {
  height: 1px;
  background-color: var(--wb-border-subtle);
}
.task-filter-menu__reset {
  display: flex;
  align-items: center;
  width: 100%;
  height: 32px;
  padding: 3px 8px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-todo-menu-text-default);
  font-size: 12px;
  line-height: 20px;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
  text-align: left;
}
.task-filter-menu__reset:hover:not(.task-filter-menu__reset--disabled) {
  background-color: var(--wb-bg-hover);
  color: var(--wb-todo-menu-text-default);
}
.task-filter-menu__reset--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.task-filter-menu__reset-label {
  flex: 1;
}
.conversation-section-add-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  margin-left: 4px;
  border-radius: 4px;
  cursor: pointer;
  color: var(--wb-icon-secondary);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.15s ease, color 0.15s ease, background-color 0.15s ease;
}
.conversation-section-add-btn svg {
  width: 16px;
  height: 16px;
  stroke-opacity: 1;
}
.conversation-section-add-btn:hover {
  color: var(--wb-color-text-primary);
  background-color: var(--wb-button-ghost-bg-hover);
}
.conversation-section-compact-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  margin-left: auto;
  border-radius: 4px;
  cursor: pointer;
  color: var(--wb-icon-secondary);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.15s ease, color 0.15s ease, background-color 0.15s ease;
}
.conversation-section-compact-btn svg {
  width: 14px;
  height: 14px;
  stroke-opacity: 1;
}
.conversation-section-compact-btn:hover {
  color: var(--wb-color-text-primary);
  background-color: var(--wb-button-ghost-bg-hover);
}
.conversation-section-motion {
  display: grid;
  width: 100%;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: 0fr;
  transition: grid-template-rows 180ms ease;
}
.conversation-section-motion.is-open {
  grid-template-rows: 1fr;
  transition: grid-template-rows 280ms ease;
}
.conversation-section-motion .conversation-section-content {
  min-height: 0;
  overflow: hidden;
  opacity: 0;
  transition: opacity 140ms ease;
}
.conversation-section-motion .conversation-section-content.is-settled {
  overflow: visible;
}
.conversation-section-motion.is-open .conversation-section-content {
  opacity: 1;
  transition: opacity 200ms ease;
}
.height-section-motion {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  transition: height 180ms ease;
