}
.wb-slot__action-btn:hover {
  opacity: 0.85;
}
.wb-slot__close-btn {
  position: absolute;
  top: 4px;
  right: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--cb-text-tertiary);
  font-size: 12px;
  cursor: pointer;
