  background: var(--cb-bg-secondary);
  border: 1px solid var(--cb-border);
}
/* ===== 保存到工作空间弹窗 ===== */
/* 品牌绿色（双主题通用） */
.keep-dialog-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}
.keep-dialog-overlay.visible {
  opacity: 1;
  pointer-events: auto;
}
.keep-dialog-modal {
  background: var(--cb-vscode-dropdown-background, #212234);
  border-radius: 12px;
  width: 480px;
  max-width: calc(100vw - 40px);
  border: 1px solid var(--cb-vscode-widget-border, #313248);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3), 0 4px 16px rgba(0, 0, 0, 0.15);
  transform: scale(0.95) translateY(8px);
  transition: transform 0.2s ease;
  overflow: hidden;
}
.keep-dialog-overlay.visible .keep-dialog-modal {
  transform: scale(1) translateY(0);
}
/* 头部区域 */
.keep-dialog-header {
  padding: 24px 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.keep-dialog-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--cb-text-primary, #d2d3e0);
  margin-bottom: 16px;
}
/* 要点列表 */
.keep-dialog-tips-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.keep-dialog-tips-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--cb-text-secondary, #858699);
  line-height: 1.8;
}
.keep-dialog-tip-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cb-text-tertiary, rgba(228, 228, 228, 0.37));
  flex-shrink: 0;
  margin-left: 2px;
  margin-right: 2px;
}
.keep-dialog-name-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.keep-dialog-name-label {
  font-size: 13px;
  line-height: 20px;
  color: var(--cb-text-primary, #d2d3e0);
}
.keep-dialog-name-input {
  height: 36px;
  padding: 0 12px;
  border: 1px solid var(--wb-color-border-primary, #3c3c3c);
  border-radius: 8px;
  background: var(--cb-vscode-editor-background, #1e1e1e);
  color: var(--cb-text-primary, #d2d3e0);
  font: inherit;
  outline: none;
}
.keep-dialog-name-input:focus {
  border-color: var(--wb-color-border-focus, #36b37e);
}
.keep-dialog-name-input--error,
.keep-dialog-name-input--error:focus {
  border-color: var(--wb-error, #ef4444);
}
.keep-dialog-name-input::placeholder {
  color: var(--cb-text-tertiary, rgba(228, 228, 228, 0.37));
}
.keep-dialog-name-error {
  color: var(--wb-error, #ef4444);
  font-size: 12px;
  line-height: 18px;
}
/* 底部按钮 */
.keep-dialog-footer {
  padding: 0 24px 24px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}
.keep-dialog-btn {
  height: 36px;
  padding: 0 20px;
  border-radius: 8px;
  font-size: 14px;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;
  border: none;
}
.keep-dialog-btn-cancel {
  background: var(--cb-vscode-editor-background, #1e1e1e);
  color: var(--cb-text-primary, #d2d3e0);
  border: 1px solid var(--cb-vscode-panel-border, #3c3c3c);
}
.keep-dialog-btn-cancel:hover {
  background: var(--cb-hover-bg, #282828);
}
.keep-dialog-btn-save {
  background: #36b37e;
  color: #fff;
}
.keep-dialog-btn-save:hover:not(:disabled) {
  background: #2ea06e;
}
.keep-dialog-btn-save:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
.keep-dialog-btn-save:active:not(:disabled) {
  background: #279660;
}
/* ===== 浅色主题覆盖 ===== */
body.light .keep-dialog-overlay,
body.vscode-light .keep-dialog-overlay {
