}
.task-list-popover-trigger {
  position: relative;
  display: flex;
  justify-content: center;
}
.task-list-popover {
  position: fixed;
  min-width: 240px;
  max-width: 320px;
  max-height: 400px;
  background: var(--cb-dropdown-bg-color, #1F1F1F);
  border: none;
  border-radius: 4px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
