  align-items: center;
  flex-shrink: 0;
}
.task-list-popover-subgroup-title {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.task-list-popover-chevron {
  flex-shrink: 0;
