  transition: none;
}
.wb-home-header__roll-cell[data-wb-swap-phase=running] {
  transition: transform var(--wb-app-swap-title-transition), opacity 0.18s ease 0.08s;
}
.wb-home-header {
  /** 进入 / 切换 / 退出：新标题从下方向上翻入。 */
}
.wb-home-header__roll-cell--current[data-wb-swap-phase=armed] {
  transform: translateY(100%);
  opacity: 0;
}
.wb-home-header__roll-cell--previous[data-wb-swap-phase=armed] {
  transform: translateY(0);
  opacity: 1;
}
.wb-home-header__roll-cell--current[data-wb-swap-phase=running] {
  transform: translateY(0);
  opacity: 1;
}
.wb-home-header__roll-cell--previous[data-wb-swap-phase=running] {
  transform: translateY(-100%);
