.wb-scene-tabs__set--current[data-wb-swap-phase=running] {
  opacity: 1;
  transform: scale(1);
  transition: opacity var(--wb-app-swap-tabs-in) var(--wb-app-swap-ease) var(--wb-app-swap-tabs-out), transform var(--wb-app-swap-tabs-in) var(--wb-app-swap-ease) var(--wb-app-swap-tabs-out);
