.vscode-dark .discover-panel-page .dc-detail-modal {
  box-shadow: 0 24px 80px var(--wb-palette-black-40);
}
:root.dark .discover-panel-page .dc-detail-stage-icon-btn,
:root.cb-dark .discover-panel-page .dc-detail-stage-icon-btn,
:root .dark .discover-panel-page .dc-detail-stage-icon-btn,
.vscode-dark .discover-panel-page .dc-detail-stage-icon-btn,
:root.dark .discover-panel-page .dc-detail-stage-close,
:root.cb-dark .discover-panel-page .dc-detail-stage-close,
:root .dark .discover-panel-page .dc-detail-stage-close,
.vscode-dark .discover-panel-page .dc-detail-stage-close {
  background: var(--wb-bg-card);
  border-color: var(--wb-border-card);
}
:root.dark .discover-panel-page .dc-detail-stage-action,
:root.cb-dark .discover-panel-page .dc-detail-stage-action,
:root .dark .discover-panel-page .dc-detail-stage-action,
.vscode-dark .discover-panel-page .dc-detail-stage-action {
  background: var(--wb-bg-card);
  border-color: var(--wb-border-card);
}
:root.dark .discover-panel-page .dc-detail-stage-action.primary,
:root.cb-dark .discover-panel-page .dc-detail-stage-action.primary,
:root .dark .discover-panel-page .dc-detail-stage-action.primary,
.vscode-dark .discover-panel-page .dc-detail-stage-action.primary {
  background: var(--wb-bg-inverse);
  border-color: var(--wb-color-text-primary);
  color: var(--wb-text-inverse);
}
:root.dark .discover-panel-page .dc-detail-stage-action.primary:hover,
:root.cb-dark .discover-panel-page .dc-detail-stage-action.primary:hover,
:root .dark .discover-panel-page .dc-detail-stage-action.primary:hover,
.vscode-dark .discover-panel-page .dc-detail-stage-action.primary:hover {
  background: var(--wb-color-bg-secondary-default);
}
:root.dark .discover-panel-page .dc-detail-stage-favorite.is-active,
:root.cb-dark .discover-panel-page .dc-detail-stage-favorite.is-active,
:root .dark .discover-panel-page .dc-detail-stage-favorite.is-active,
.vscode-dark .discover-panel-page .dc-detail-stage-favorite.is-active {
  background: var(--wb-favorite-bg-soft);
}
:root.dark .discover-panel-page .dc-detail-tool-chip,
:root.cb-dark .discover-panel-page .dc-detail-tool-chip,
:root .dark .discover-panel-page .dc-detail-tool-chip,
.vscode-dark .discover-panel-page .dc-detail-tool-chip {
  background: var(--wb-bg-tertiary);
}
:root.dark .discover-panel-page .dc-source-panel,
:root.cb-dark .discover-panel-page .dc-source-panel,
:root .dark .discover-panel-page .dc-source-panel,
.vscode-dark .discover-panel-page .dc-source-panel {
  background: var(--wb-bg-card);
}
:root.dark .discover-panel-page .dc-source-panel-backdrop,
:root.cb-dark .discover-panel-page .dc-source-panel-backdrop,
:root .dark .discover-panel-page .dc-source-panel-backdrop,
.vscode-dark .discover-panel-page .dc-source-panel-backdrop {
  background: var(--wb-color-mask-color);
}
:root.dark .discover-panel-page .dc-detail-prompt-block,
:root.cb-dark .discover-panel-page .dc-detail-prompt-block,
:root .dark .discover-panel-page .dc-detail-prompt-block,
.vscode-dark .discover-panel-page .dc-detail-prompt-block {
  background: var(--wb-bg-secondary);
}
:root.dark .discover-panel-page .dc-category-tab.is-active,
:root.cb-dark .discover-panel-page .dc-category-tab.is-active,
:root .dark .discover-panel-page .dc-category-tab.is-active,
.vscode-dark .discover-panel-page .dc-category-tab.is-active {
  background: var(--wb-bg-hover);
}
:root.dark .discover-panel-page .sidebar__icon:hover,
:root.cb-dark .discover-panel-page .sidebar__icon:hover,
:root .dark .discover-panel-page .sidebar__icon:hover,
.vscode-dark .discover-panel-page .sidebar__icon:hover {
  background: var(--wb-bg-hover);
}
/* ===== 高对比度 ===== */
.vscode-high-contrast .discover-panel-page {
  --dc-border: var(--wb-border-teams);
  --dc-text-primary: var(--wb-text-white);
}
.vscode-high-contrast-light .discover-panel-page {
  --dc-border: #0f4a85;
  --dc-text-primary: var(--wb-color-text-solid);
}
/* ===== 页面容器 ===== */
.discover-panel-page {
  --dc-page-gutter: 24px;
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: var(--wb-home-bg-secondary);
  color: var(--wb-color-text-primary);
}
.discover-panel-page.is-inactive {
  opacity: 0.96;
}
/* ===== TopBar 返回按钮 ===== */
.dc-topbar-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 500;
  color: var(--wb-text-weak);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  background: none;
  border: none;
  font-family: inherit;
  transition: all 0.12s;
  white-space: nowrap;
  -webkit-app-region: no-drag;
}
.dc-topbar-back-btn svg {
  width: 12px;
  height: 12px;
  stroke-width: 1;
}
.dc-topbar-back-btn:hover {
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
}
.dc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 0 var(--dc-page-gutter);
  flex-shrink: 0;
  margin-bottom: 16px;
}
.dc-header-left {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.dc-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  align-self: center;
}
.dc-title {
  margin: 0;
  font-size: 24px;
  line-height: 1.25;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  letter-spacing: 0;
}
.dc-subtitle {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--wb-text-weak);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* ===== playbook grid 自定义滚动条 ===== */
.dc-playbook-grid {
  scrollbar-width: thin;
  scrollbar-color: var(--wb-border-card) transparent;
}
.dc-playbook-grid::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
.dc-playbook-grid::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 2px;
}
.dc-playbook-grid::-webkit-scrollbar-thumb {
  background: var(--wb-border-card);
  border-radius: 2px;
  transition: background 0.2s ease;
}
.dc-playbook-grid::-webkit-scrollbar-thumb:hover {
  background: var(--wb-bg-tertiary);
}
/* ===== 分类 Tab ===== */
/* 外层容器：ScrollList wrapper，接管左右渐变遮罩 + 拖动 + 滚轮水平化 */
.dc-category-tabs {
  padding: 12px var(--dc-page-gutter);
  flex-shrink: 0;
}
.dc-category-tab {
  display: inline-flex;
  align-items: center;
  height: 28px;
  padding: 4px 12px;
  border-radius: 6px;
  background: transparent;
  border: none;
  color: var(--wb-text-weak);
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
  flex-shrink: 0;
  font-family: inherit;
  letter-spacing: 0;
}
/* 未选中态 hover：背景轻微高亮 + 文字加深 */
.dc-category-tab:hover:not(.is-active) {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
.dc-category-tab.is-active {
  color: var(--wb-color-text-primary);
  background: var(--wb-bg-inset-strong);
  font-weight: 500;
}
.dc-category-icon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
.dc-category-emoji {
  font-size: 14px;
  line-height: 1;
}
.dc-case-count {
  font-size: 12px;
  color: var(--wb-text-weak);
}
.dc-category-tab.is-active .dc-case-count {
  color: var(--wb-control-primary-alt);
  opacity: 0.7;
}
/* ===== 官方精选区域 ===== */
.dc-featured-section {
  padding: 0 var(--dc-page-gutter);
  margin-bottom: 24px;
  flex-shrink: 0;
}
.dc-featured-section-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}
.dc-featured-section-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  letter-spacing: -0.01em;
}
.dc-featured-refresh-btn {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 11px;
  font-weight: 400;
  color: var(--wb-text-weak);
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  transition: all 0.15s;
  white-space: nowrap;
  font-family: inherit;
}
.dc-featured-refresh-btn svg {
  width: 10px;
  height: 10px;
  transition: transform 0.3s ease;
}
.dc-featured-refresh-btn:hover:not(:disabled) {
  color: var(--wb-control-primary-alt);
  background: var(--wb-bg-hover);
}
.dc-featured-refresh-btn:active svg {
  transform: rotate(180deg);
}
.dc-featured-refresh-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.dc-featured-scroll-wrapper {
  position: relative;
}
.dc-featured-scroll {
  display: flex;
  gap: 20px;
}
.dc-featured-scroll > * {
  flex: 1;
  min-width: 0;
}
/* ===== 精选卡片 ===== */
.dc-featured-card {
  position: relative;
  display: flex;
  flex-direction: column;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--wb-border-card);
  background: var(--wb-bg-card);
  transition: none;
  cursor: pointer;
}
.dc-featured-card:hover,
.dc-featured-card.is-hovered {
  border-color: var(--wb-border-card);
}
.dc-featured-cover {
  position: relative;
  width: 100%;
  height: 120px;
  overflow: hidden;
}
.dc-featured-cover-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: var(--wb-bg-tertiary);
  opacity: 0.6;
}
.dc-featured-favorite-btn {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 50%;
  background: var(--wb-bg-scrim-light);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s ease, background 0.15s ease, opacity 0.15s ease;
  z-index: 2;
  opacity: 0;
  pointer-events: none;
}
.dc-featured-card:hover .dc-featured-favorite-btn,
.dc-featured-card.is-hovered .dc-featured-favorite-btn {
  opacity: 1;
  pointer-events: auto;
}
.dc-featured-favorite-btn.is-favorite {
  opacity: 1;
  pointer-events: auto;
}
.dc-featured-favorite-btn:hover {
  transform: scale(1.1);
  background: var(--wb-bg-card);
}
.dc-featured-favorite-btn svg {
  width: 12px;
  height: 12px;
  color: var(--wb-text-weak);
  transition: color 0.15s ease;
}
.dc-featured-favorite-btn:hover svg {
  color: var(--wb-control-primary-alt);
}
.dc-featured-favorite-btn.is-favorite svg {
  color: var(--wb-control-primary-alt);
}
.dc-featured-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 14px 16px 16px;
}
.dc-featured-title {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}
.dc-featured-subtitle {
  margin: 0 0 12px;
  font-size: 13px;
  color: var(--wb-text-weak);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  flex: 1;
}
.dc-featured-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: auto;
}
.dc-featured-artifact-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 12px;
  color: var(--wb-control-primary-alt);
  background: var(--wb-bg-hover);
}
.dc-artifact-icon {
  font-size: 14px;
}
.dc-featured-usage {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--wb-text-weak);
}
.dc-featured-usage svg {
  width: 14px;
  height: 14px;
}
/* ===== 按场景浏览区域 ===== */
.dc-browse-section {
  position: relative;
}
.dc-browse-section-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}
.dc-browse-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px var(--dc-page-gutter) 0;
  top: 0;
  z-index: 10;
  background: var(--wb-bg-primary);
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s;
}
.dc-browse-section-header.is-stuck {
  border-bottom-color: var(--wb-border-card);
}
/* 收藏筛选按钮 — 对齐 mockup .inspiration-favorite-btn */
.dc-fav-filter-btn {
  height: 36px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 13px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  background: var(--wb-bg-card);
  border: 1px solid var(--wb-border-card);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
  white-space: nowrap;
  font-family: inherit;
  line-height: 1.2;
}
.dc-fav-filter-btn svg {
  flex-shrink: 0;
}
.dc-fav-filter-btn:hover {
  background: var(--wb-bg-hover);
  border-color: var(--wb-border-hover);
  color: var(--wb-color-text-primary);
}
.dc-fav-filter-btn.is-active {
  background: var(--wb-bg-hover);
  border-color: var(--wb-border-hover);
  color: var(--wb-color-text-primary);
  font-weight: 600;
}
.dc-fav-count {
  min-width: 16px;
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--wb-bg-inverse);
  color: var(--wb-text-on-inverse);
  font-size: 10px;
  line-height: 1;
  font-weight: 600;
}
/* 收藏为空的内联提示 */
.dc-fav-empty-inline {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  color: var(--wb-text-medium);
  gap: 8px;
}
.dc-fav-empty-inline svg {
  width: 24px;
  height: 24px;
  opacity: 0.25;
}
.dc-fav-empty-inline span {
  font-size: 13px;
}
.dc-fav-empty-inline .dc-fav-empty-hint {
  font-size: 11px;
  color: var(--wb-text-medium);
  opacity: 0.7;
}
/* 收藏视图头部 — 对齐 mockup .fav-mode-header */
.dc-fav-mode-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px var(--dc-page-gutter) 0;
}
/* 返回按钮 — 对齐 mockup .fav-mode-header__back（pill 轮廓按钮） */
.dc-fav-topbar,
.dc-mobile-topbar {
  display: flex;
  align-items: center;
  padding: 0 16px;
  -webkit-app-region: drag;
}
.dc-fav-topbar button,
.dc-mobile-topbar button {
  -webkit-app-region: no-drag;
}
.dc-fav-mode-header-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-text-medium);
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.dc-fav-mode-header-back svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
.dc-fav-mode-header-back:hover {
  background: var(--wb-bg-secondary);
  color: var(--wb-color-text-primary);
}
/* 标题 — 对齐 mockup .fav-mode-header__title */
.dc-fav-mode-header-title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--wb-color-text-primary);
}
.dc-fav-mode-header-title svg {
  width: 16px;
  height: 16px;
  color: var(--wb-control-primary-alt);
}
/* 数量 pill — 对齐 mockup .fav-mode-header__count */
.dc-fav-mode-header-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.4;
  color: var(--wb-text-medium);
  background: var(--wb-bg-secondary);
}
.dc-content-wrapper {
  flex: 1;
  min-height: 0;
  overflow-y: scroll;
  overflow-x: hidden;
  padding-top: 4px;
  /* 勿设标准属性 scrollbar-width/color：会覆盖下方 ::-webkit-scrollbar 的宽度，导致占位算不准 */
  --dc-scrollbar-width: 6px;
  /* 子元素右外扩一个滚动条宽度，让滚动条浮在右侧 gutter 留白上，保证左右留白一致 */
}
.dc-content-wrapper > * {
  margin-right: calc(-1 * var(--dc-scrollbar-width));
}
.dc-content-wrapper::-webkit-scrollbar {
  width: var(--dc-scrollbar-width);
}
.dc-content-wrapper::-webkit-scrollbar-track {
  background: transparent;
}
.dc-content-wrapper::-webkit-scrollbar-thumb {
  background-color: transparent;
  border-radius: 3px;
}
.dc-content-wrapper:hover::-webkit-scrollbar-thumb {
  background-color: var(--wb-border-card);
}
.dc-content-wrapper:hover::-webkit-scrollbar-thumb:hover {
  background-color: var(--wb-bg-tertiary);
}
/* ===== 搜索样式 ===== */
.dc-search-wrapper {
  position: relative;
  width: 220px;
  min-width: 180px;
  flex-shrink: 0;
}
.dc-search-input {
  width: 100%;
  height: 36px;
  padding: 0 12px 0 36px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: var(--wb-bg-secondary);
  font-size: 13px;
  line-height: 36px;
  color: var(--wb-color-text-primary);
  outline: none;
  font-family: inherit;
  transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
}
.dc-search-input::placeholder {
  color: var(--wb-text-weak);
}
.dc-search-input:hover {
  border-color: var(--wb-border-hover);
}
.dc-search-input:focus {
  background: var(--wb-bg-secondary);
  border-color: var(--wb-border-hover);
  box-shadow: none;
}
.dc-search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: var(--wb-text-weak);
  pointer-events: none;
  stroke-width: 2;
  transition: color 0.2s ease;
}
.dc-search-input:focus ~ .dc-search-icon {
  color: var(--wb-text-weak);
}
.dc-search-clear {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--wb-text-medium);
  font-size: 12px;
  cursor: pointer;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: opacity 0.15s ease;
}
.dc-search-clear.is-visible {
  display: flex;
}
.dc-search-clear:hover {
  opacity: 0.8;
}
.dc-search-highlight {
  background: var(--wb-bg-active);
  color: var(--wb-color-text-solid);
  border-radius: 2px;
  padding: 0 1px;
}
.dc-search-result-hint {
  display: none;
  padding: 12px var(--dc-page-gutter) 0;
  font-size: 13px;
  color: var(--wb-text-weak);
}
.dc-search-result-hint.is-visible {
  display: block;
}
.dc-search-result-hint .keyword {
  color: var(--wb-control-primary-alt);
  font-weight: 500;
}
.dc-search-result-hint .count {
  color: var(--wb-color-text-primary);
  font-weight: 600;
}
/* ===== 网格（瀑布流布局） ===== */
.dc-playbook-grid {
  padding: 24px var(--dc-page-gutter) 32px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-items: start;
  gap: 18px;
  align-content: start;
}
/* 瀑布流列容器 */
.dc-masonry-column {
  display: flex;
  flex-direction: column;
  gap: 18px;
  min-width: 0;
}
/* ===== 卡片 ===== */
.dc-playbook-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--wb-border-card);
  background: var(--wb-bg-card);
  transition: none;
  cursor: pointer;
}
.dc-playbook-card:hover,
.dc-playbook-card.is-hovered {
  border-color: var(--wb-border-card);
}
.dc-card-cover {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: var(--wb-bg-tertiary);
  overflow: hidden;
}
/* 竖向封面（如 HTML 模板）—— 由 .dc-card-cover-portrait 修饰 */
.dc-card-cover.dc-card-cover-portrait {
  aspect-ratio: 9 / 16;
}
.dc-card-cover img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
/* 竖向封面图从顶部对齐 */
.dc-card-cover.dc-card-cover-portrait img {
  object-position: top center;
}
.dc-card-cover-placeholder {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--wb-bg-tertiary);
}
.dc-card-cover-placeholder svg {
  width: 48px;
  height: 48px;
  color: var(--wb-control-primary-alt);
  opacity: 0.5;
}
.dc-card-favorite-btn {
  width: 20px;
  height: 20px;
  border: none;
  border-radius: 999px;
  background: transparent;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s ease;
  flex-shrink: 0;
  color: var(--wb-text-weak);
}
.dc-card-favorite-btn.is-favorite {
  color: var(--wb-status-error-vivid);
}
.dc-card-favorite-btn:hover {
  background: transparent;
  color: var(--wb-text-medium);
}
.dc-card-favorite-btn svg {
  width: 14px;
  height: 14px;
  min-width: 14px;
  flex-shrink: 0;
  color: inherit;
  transition: color 0.15s ease;
}
.dc-card-favorite-btn.is-favorite svg {
  color: var(--wb-status-error-vivid);
}
.dc-card-favorite-btn.is-favorite:hover {
  color: var(--wb-status-error-vivid);
}
.dc-card-info {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 12px;
  flex: 1;
}
.dc-card-category {
  display: inline-block;
  margin-bottom: 8px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 500;
  color: var(--wb-control-primary-alt);
  background: var(--wb-bg-hover);
  width: fit-content;
}
.dc-card-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 16px;
  min-width: 0;
}
.dc-card-title {
  flex: 1;
  min-width: 0;
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  line-height: 16px;
  letter-spacing: 0;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}
.dc-card-artifact-type {
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  padding: 0 7px;
  border-radius: 5px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-weak);
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1;
}
.dc-card-subtitle {
  max-width: none;
  margin: 2px 0 0;
  font-size: 11px;
  color: var(--wb-text-medium);
  line-height: 14px;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
.dc-card-meta {
  display: none;
}
.dc-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
  flex-shrink: 0;
  min-height: 0;
  color: var(--wb-text-weak);
  font-size: 10.5px;
  font-weight: 600;
  border-top: none;
}
/* 精选 Badge — footer 内 */
.dc-card-featured-badge {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 7px;
  border-radius: 5px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-weak);
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}
/* 类型徽章 — footer 内（颜色由组件内联 style 按 artifact 类型给出） */
.dc-card-type-badge {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 7px;
  border-radius: 5px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-weak);
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0;
  white-space: nowrap;
}
/* 5.5.0 MMVP 模块 1：卡片 footer 作者信息（头像 + 昵称）
 * - 头像 16×16 圆形；预留稳定占位避免异步加载引发卡片跳动
 * - 昵称单行省略，宽度由 footer 剩余空间决定（右侧 usage/favorite 优先） */
.dc-card-creator {
  flex: 1;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--wb-color-text-secondary);
}
.dc-card-creator-avatar {
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  object-fit: cover;
  display: block;
  /* 未加载完前保留稳定占位（浅灰底），避免 img 高度塌成 0 引发卡片抖动 */
  background: var(--wb-bg-hover);
}
.dc-card-creator-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.3;
  color: var(--wb-color-text-secondary);
}
.dc-card-artifact-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 500;
}
.dc-card-artifact-tag svg {
  width: 10px;
  height: 10px;
  stroke-width: 1;
}
.dc-card-usage {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10.5px;
  color: var(--wb-text-weak);
  font-weight: 600;
}
.dc-card-usage svg {
  display: none;
}
.dc-card-footer-right {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.dc-card-usage svg {
  display: none;
}
/* ===== 空状态 ===== */
.dc-empty-state {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  color: var(--wb-text-weak);
  padding: 60px 20px;
}
.dc-empty-icon {
  width: 64px;
  height: 64px;
  margin-bottom: 14px;
  color: var(--wb-border-card);
}
.dc-empty-state p {
  margin: 0;
  font-size: 14px;
}
.dc-empty-state button {
  cursor: pointer;
}
/* ===== Loading 状态 ===== */
.dc-loading-overlay {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  background: color-mix(in srgb, var(--wb-bg-primary) 90%, transparent);
}
.dc-spinner {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 3px solid var(--wb-bg-hover);
  border-top-color: var(--wb-control-primary-alt);
  animation: dc-spin 1s linear infinite;
}
.dc-loading-message {
  margin: 14px 0 0;
  font-size: 13px;
  color: var(--wb-text-medium);
}
@keyframes dc-spin {
  to {
    transform: rotate(360deg);
  }
}
/* ===== 收藏按钮 (Header) ===== */
.dc-favorites-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}
.dc-favorites-btn:hover {
  border-color: var(--wb-status-error-vivid);
  color: var(--wb-status-error-vivid);
  background: var(--wb-favorite-bg-soft);
}
.dc-favorites-btn svg {
  width: 16px;
  height: 16px;
}
.dc-favorites-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  font-size: 11px;
  font-weight: 600;
  background: var(--wb-status-error-vivid);
  color: var(--wb-text-white);
}
/* ===== 响应式 ===== */
@media (max-width: 980px) {
  .dc-playbook-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767px) {
  .discover-panel-page {
    --dc-page-gutter: 20px;
  }
  .dc-header {
    flex-direction: column;
    gap: 12px;
  }
  .dc-search-wrapper {
    width: 100%;
    flex: 1;
  }
  .dc-category-tab {
    padding: 4px 12px;
  }
  .dc-playbook-grid {
    padding: 20px var(--dc-page-gutter);
    gap: 16px;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 575px) {
  .dc-playbook-grid {
    grid-template-columns: 1fr;
  }
}
/* ===== 详情弹窗（旧模态框，已弃用，保留 backdrop 供兼容） ===== */
.dc-detail-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--wb-color-mask-color);
  padding: 24px;
}
.dc-detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid var(--wb-border-light-alt);
  flex-shrink: 0;
}
.dc-detail-title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
}
.dc-detail-header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.dc-detail-favorite-btn,
.dc-detail-close-btn {
  width: 36px;
  height: 36px;
  border: none;
  border-radius: 8px;
  background: var(--wb-bg-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s ease, color 0.2s ease;
}
.dc-detail-favorite-btn svg,
.dc-detail-close-btn svg {
  width: 20px;
  height: 20px;
  color: var(--wb-text-weak);
}
.dc-detail-favorite-btn:hover,
.dc-detail-close-btn:hover {
  background: var(--wb-bg-hover);
}
.dc-detail-favorite-btn.is-favorite svg {
  color: var(--wb-control-primary-alt);
}
.dc-detail-content {
  flex: 1;
  overflow-y: auto;
  padding: 24px;
}
.dc-detail-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 60px 0;
}
.dc-detail-error {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 0;
  color: var(--wb-status-error-vivid);
}
.dc-detail-section {
  margin-bottom: 24px;
}
.dc-detail-section:last-child {
  margin-bottom: 0;
}
.dc-detail-section h3 {
  margin: 0 0 12px;
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
}
.dc-detail-description {
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  color: var(--wb-text-medium);
}
.dc-detail-prompt {
  margin: 0;
  padding: 16px;
  background: var(--wb-bg-secondary);
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--wb-color-text-primary);
  font-family: 'SF Mono', 'Monaco', 'Consolas', monospace;
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 200px;
  overflow-y: auto;
}
.dc-detail-resources {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}
.dc-resource-group {
  flex: 1;
  min-width: 180px;
  padding: 14px;
  background: var(--wb-bg-secondary);
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
}
.dc-resource-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
}
.dc-resource-header svg {
  width: 16px;
  height: 16px;
  color: var(--wb-control-primary-alt);
}
.dc-resource-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.dc-resource-list li {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
  font-size: 13px;
  color: var(--wb-text-medium);
}
.dc-required-badge {
  padding: 2px 6px;
  font-size: 10px;
  font-weight: 500;
  color: var(--wb-status-warning-vivid);
  background: var(--wb-bg-warning-vivid-soft);
  border-radius: 4px;
}
.dc-no-resources {
  margin: 0;
  font-size: 13px;
  color: var(--wb-text-weak);
}
.dc-artifacts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 12px;
}
.dc-artifact-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px;
  background: var(--wb-bg-secondary);
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
  cursor: pointer;
  transition: border-color 0.2s ease;
}
.dc-artifact-card:hover {
  border-color: var(--wb-control-primary-alt);
}
.dc-artifact-preview {
  width: 80px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--wb-bg-tertiary);
  border-radius: 4px;
  overflow: hidden;
}
.dc-artifact-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.dc-artifact-type-icon {
  font-size: 24px;
}
.dc-artifact-name {
  font-size: 12px;
  color: var(--wb-text-medium);
  text-align: center;
  word-break: break-word;
}
.dc-detail-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding: 16px 24px;
  border-top: 1px solid var(--wb-border-light-alt);
  flex-shrink: 0;
}
.dc-detail-cancel-btn {
  padding: 10px 20px;
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s ease;
}
.dc-detail-cancel-btn:hover {
  background: var(--wb-bg-hover);
}
.dc-detail-launch-btn {
  padding: 10px 24px;
  border: none;
  border-radius: 8px;
  background: var(--wb-button-gradient-alt);
  color: var(--wb-text-on-primary);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  box-shadow: 0 4px 12px color-mix(in srgb, var(--wb-accent-blue) 30%, transparent);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.dc-detail-launch-btn:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 6px 16px color-mix(in srgb, var(--wb-accent-blue) 40%, transparent);
}
.dc-detail-launch-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
/* ===== 收藏抽屉 ===== */
.dc-drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: transparent;
  opacity: 0;
  transition: opacity 0.3s ease, background 0.3s ease;
}
.dc-drawer-backdrop.is-visible {
  opacity: 1;
  background: var(--wb-bg-overlay);
}
.dc-drawer {
  position: fixed;
  top: 0;
  right: 0;
  width: 380px;
  max-width: 100%;
  height: 100%;
  background: var(--wb-bg-primary);
  box-shadow: -8px 0 24px var(--wb-palette-black-10);
  transform: translateX(100%);
  transition: transform 0.35s cubic-bezier(0.32, 0.72, 0, 1);
  display: flex;
  flex-direction: column;
}
.dc-drawer.is-open {
  transform: translateX(0);
}
.dc-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 20px;
  border-bottom: 1px solid var(--wb-border-light-alt);
  flex-shrink: 0;
}
.dc-drawer-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
}
.dc-drawer-close-btn {
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 6px;
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s ease;
}
.dc-drawer-close-btn svg {
  width: 18px;
  height: 18px;
  color: var(--wb-text-weak);
}
.dc-drawer-close-btn:hover {
  background: var(--wb-bg-hover);
}
.dc-drawer-content {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}
.dc-favorites-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.dc-favorites-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.2s ease, opacity 0.2s ease;
  opacity: 0;
  transform: translateX(20px);
  animation: dc-slide-in-item 0.3s ease forwards;
}
/* 列表项交错动画 */
@keyframes dc-slide-in-item {
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
.dc-favorites-item:nth-child(1) {
  animation-delay: 0.05s;
}
.dc-favorites-item:nth-child(2) {
  animation-delay: 0.1s;
}
.dc-favorites-item:nth-child(3) {
  animation-delay: 0.15s;
}
.dc-favorites-item:nth-child(4) {
  animation-delay: 0.2s;
}
.dc-favorites-item:nth-child(5) {
  animation-delay: 0.25s;
}
.dc-favorites-item:nth-child(6) {
  animation-delay: 0.3s;
}
.dc-favorites-item:nth-child(n+7) {
  animation-delay: 0.35s;
}
.dc-favorites-item:hover {
  background: var(--wb-bg-hover);
}
.dc-favorites-item-cover {
  width: 60px;
  height: 45px;
  border-radius: 6px;
  overflow: hidden;
  background: var(--wb-bg-tertiary);
  flex-shrink: 0;
}
.dc-favorites-item-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.dc-favorites-item-placeholder {
  width: 100%;
  height: 100%;
  background: var(--wb-bg-tertiary);
}
.dc-favorites-item-info {
  flex: 1;
  min-width: 0;
}
.dc-favorites-item-title {
  margin: 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--wb-color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.dc-favorites-item-subtitle {
  margin: 4px 0 0;
  font-size: 12px;
  color: var(--wb-text-weak);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.dc-favorites-item-remove {
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 6px;
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.2s ease, background 0.2s ease;
  flex-shrink: 0;
}
.dc-favorites-item:hover .dc-favorites-item-remove {
  opacity: 1;
}
.dc-favorites-item-remove svg {
  width: 16px;
  height: 16px;
  color: var(--wb-text-weak);
}
.dc-favorites-item-remove:hover {
