  border: 1px solid var(--wb-border-card);
  border-bottom: 0;
  overflow: hidden;
  background: var(--wb-bg-card);
  display: flex;
  flex-direction: column;
}
/* 响应式 - 详情页面 */
@media (max-width: 900px) {
  .dc-detail-page-body {
    flex-direction: column;
    overflow: scroll;
  }
  .dc-detail-left {
    flex: none;
    padding: 12px 12px 0;
  }
  .dc-detail-right {
    width: auto;
    flex: 0 0 42%;
    border-left: none;
    border-top: 1px solid var(--wb-border-card);
    padding: 20px;
    overflow: visible;
  }
}
@media (max-width: 575px) {
  .dc-detail-left {
    padding: 12px 12px 0;
  }
  .dc-detail-right {
    padding: 16px;
  }
  .dc-detail-page-title {
    font-size: 16px;
  }
}
/* ============ 紧凑案例预览面板（案例二级页 / 口令入口，#100032 #99356）============ */
.wb-modal.dc-detail-modal.dc-case-preview-modal {
