  padding: 0 12px;
  height: 30px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 500;
  color: var(--wb-color-text-secondary);
  background: var(--wb-bg-secondary);
  border: 1px solid var(--wb-border-default);
  white-space: nowrap;
  box-sizing: border-box;
}
.ec-modal-skill-icon {
  font-size: 13px;
  line-height: 1;
}
/* 成员行（参考 modal-team-member 样式） */
.ec-modal-team-member {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}
.ec-modal-team-member:last-child {
  border-bottom: none;
}
.ec-modal-member-avatar {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  overflow: hidden;
  flex-shrink: 0;
  background: var(--wb-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
}
.ec-modal-member-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.ec-modal-member-avatar-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
  color: var(--wb-button-primary-fg);
}
.ec-modal-member-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  flex-wrap: nowrap;
}
.ec-modal-member-name {
  font-size: 11px;
  color: var(--wb-color-text-tertiary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 0 1 auto;
  min-width: 0;
}
.ec-modal-member-role {
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  white-space: nowrap;
  flex-shrink: 0;
}
/* 主理人标识 */
.ec-modal-leader-badge {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 3px;
  padding: 1px 6px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 600;
  background: var(--wb-bg-warning-soft-strong);
  color: var(--wb-badge-warning-fg);
  white-space: nowrap;
  flex-shrink: 0;
}
.expert-center-dark .ec-modal-leader-badge {
  background: var(--wb-palette-white-20);
  color: var(--wb-palette-white-80);
}
.expert-center-dark .ec-modal-leader-badge .ec-modal-leader-badge-icon {
  filter: grayscale(1) invert(1);
  opacity: 0.8;
}
/* 弹框底部：召唤按钮 */
.ec-modal-footer {
  display: flex;
  justify-content: center;
  flex-shrink: 0;
  padding: 16px 20px 20px;
  border-top: 1px solid var(--wb-border-default);
  background: var(--wb-bg-primary);
}
.expert-center-dark .ec-modal-footer {
  border-top: 1px solid color-mix(in srgb, var(--wb-color-text-tertiary) 10%, transparent);
}
.ec-modal-summon-btn {
  width: 100%;
  height: 42px;
  padding: 0 24px;
  border: none;
  border-radius: 8px;
  background: var(--wb-button-primary-bg);
  color: var(--wb-button-primary-fg);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, opacity 0.15s ease, transform 0.15s ease;
  letter-spacing: 0.2px;
}
.ec-modal-summon-btn:hover {
  background: var(--wb-button-primary-bg-hover);
  opacity: 0.96;
}
.ec-modal-summon-btn:active {
  transform: translateY(0);
}
.ec-finance-risk-dialog-title {
  display: inline-flex;
  align-items: center;
  font-weight: 600;
}
.ec-confirm-dialog-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.ec-confirm-dialog-checkbox-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.ec-confirm-dialog-checkbox {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: inherit;
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
}
.ec-confirm-dialog-checkbox input {
  margin: 0;
  accent-color: currentColor;
}
.ec-finance-risk-confirm-overlay[data-theme="dark"] [style*="--cb-button-dark-background"] {
  color: var(--wb-button-primary-fg) !important;
}
.ec-finance-risk-confirm-overlay[data-theme="dark"] [style*="--cb-button-dark-background"]:hover:not(:disabled),
.ec-finance-risk-confirm-overlay[data-theme="dark"] [style*="--cb-button-dark-background"]:active:not(:disabled) {
  background-color: var(--wb-button-primary-bg-active) !important;
}
/* ===== 我的专家 (My Experts Panel) ===== */
.ec-my-panel {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  padding: 20px var(--ec-content-gutter);
}
/* 子 Tab 切换器 */
.ec-my-sub-tabs {
  display: inline-flex;
  gap: 4px;
  margin-bottom: 24px;
  align-items: center;
  background: var(--wb-bg-tertiary);
  border-radius: 12px;
  padding: 4px;
}
.ec-my-sub-tab {
  padding: 8px 22px;
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-color-text-tertiary);
  cursor: pointer;
  border: none;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  letter-spacing: -0.1px;
  background: transparent;
  border-radius: 9px;
  position: relative;
}
.ec-my-sub-tab:hover {
  color: var(--wb-color-text-secondary);
}
.ec-my-sub-tab.is-active {
  color: var(--wb-color-text-primary);
  font-weight: 700;
  background: var(--wb-bg-card);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}
/* 最近使用提示栏 */
.ec-my-recent-hint {
  font-size: 12px;
  color: var(--wb-color-text-tertiary);
  margin-bottom: 18px;
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--wb-brand-accent-bg);
  padding: 10px 16px;
  border-radius: 10px;
  font-weight: 500;
}
.ec-my-recent-hint svg {
  width: 14px;
  height: 14px;
  color: var(--wb-brand-accent);
  flex-shrink: 0;
}
.ec-my-created-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--wb-spacing-4);
  margin-bottom: var(--wb-spacing-5);
}
.ec-my-created-tabs {
  min-width: 0;
}
.ec-my-created-tab-count {
  flex-shrink: 0;
  display: flex;
  padding: 0px 6px;
  justify-content: center;
  align-items: center;
  background: rgba(0, 0, 0, 0.06);
  border-radius: 10px;
  color: var(--color-text-tertiary, rgba(0, 0, 0, 0.5));
  font-family: "PingFang SC";
  font-size: 12px;
  font-weight: 500;
  font-style: normal;
  text-decoration-line: none;
  line-height: 20px;
}
.ec-my-cloud-upload-all {
  margin-left: auto;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  height: 28px;
  padding: 0 6px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-color-text-tertiary);
  font-size: 13px;
  font-weight: 400;
  line-height: 20px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.ec-my-cloud-upload-all:hover:not(:disabled) {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
.ec-my-cloud-upload-all:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}
.ec-my-cloud-upload-all__icon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
@media (max-width: 540px) {
  .ec-my-created-toolbar {
    flex-wrap: wrap;
  }
}
/* 最近使用 & 我创建的 网格（与 .ec-expert-grid 对齐） */
.ec-my-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(288px, 1fr));
  gap: 12px;
  align-content: start;
}
.ec-my-grid.is-search-empty {
  grid-template-columns: minmax(0, 1fr) minmax(min(288px, 100%), 1fr) minmax(0, 1fr);
}
.ec-my-grid.is-search-empty .ec-create-card {
  grid-column: 2;
}
/* 最近使用空态 */
.ec-my-recent-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 15% 40px 60px;
}
.ec-my-recent-empty-icon {
  width: 72px;
  height: 72px;
  background: linear-gradient(145deg, #f0edff, #e5deff);
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 32px;
  box-shadow: 0 4px 16px rgba(124, 92, 252, 0.1);
}
.expert-center-dark .ec-my-recent-empty-icon {
  background: linear-gradient(145deg, #2d2a3e, #3a3550);
}
.ec-my-recent-empty-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-color-text-secondary);
  margin: 0 0 4px;
}
.ec-my-recent-empty-hint {
  font-size: 12px;
  color: var(--wb-color-text-tertiary);
  margin: 0;
  font-weight: 400;
}
/* 创建卡片：外观对齐 Ardot 专家卡片节点 30583:1133，内容保持创建入口居中。 */
.ec-create-card {
  flex-shrink: 0;
  display: flex;
  height: 150px;
  box-sizing: border-box;
  padding: var(--wb-spacing-5) var(--wb-spacing-6);
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--wb-spacing-4);
  background: var(--wb-bg-card);
  border: 1px solid var(--wb-border-card-static);
  border-radius: var(--wb-radius-2xl);
  box-shadow: var(--wb-shadow-card-soft);
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}
.ec-create-card:hover {
  border-color: var(--wb-border-hover);
  background: var(--wb-bg-hover);
}
.ec-create-card-icon {
  width: 18px;
  height: 18px;
  display: block;
  object-fit: contain;
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}
.ec-create-card:hover .ec-create-card-icon {
  transform: scale(1.05);
}
.ec-create-card-label {
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
  font-weight: 600;
  letter-spacing: -0.1px;
}
.ec-create-card:hover .ec-create-card-label {
  color: var(--wb-brand-accent);
}
.ec-cr-card {
  position: relative;
}
/* “我的专家”卡片右上角同时悬浮“云同步 / 更多 / 召唤”，标题需避开完整操作区，避免长名称覆盖菜单入口。 */
.ec-cr-card .ec-card-title-row {
  width: 100%;
  box-sizing: border-box;
  padding-right: calc(var(--wb-spacing-12) + var(--wb-spacing-8) + var(--wb-spacing-8) + var(--wb-spacing-6));
}
/* 固定宽度同时容纳中文“召唤”和英文“Summon”，保证与左侧更多按钮保持稳定间距。 */
.ec-cr-card .ec-card-summon-btn--top {
  width: calc(var(--wb-spacing-12) + var(--wb-spacing-2));
  box-sizing: border-box;
}
.ec-cr-card--menu-open {
  overflow: visible;
  z-index: 20;
}
.ec-cr-card .ec-card-summon-btn--top::before {
  width: var(--wb-spacing-3);
}
.ec-cr-cloud-icon {
  position: absolute;
  top: 18px;
  right: calc(var(--wb-spacing-12) + var(--wb-spacing-8) + var(--wb-spacing-8));
  z-index: 3;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 2px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--wb-color-text-primary);
  cursor: pointer;
  pointer-events: auto;
}
.ec-cr-cloud-icon:hover:not(.is-loading):not(.is-disabled) {
  background: var(--wb-bg-hover);
}
.ec-cr-cloud-icon.is-disabled {
  cursor: default;
}
.ec-cr-cloud-icon.is-loading {
  cursor: not-allowed;
  opacity: 0.72;
}
.ec-cr-cloud-icon__svg {
  width: 16px;
  height: 16px;
  display: block;
}
.ec-cr-cloud-icon__spinner {
  width: 12px;
  height: 12px;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: ec-cloud-action-spin 0.8s linear infinite;
}
@keyframes ec-cloud-action-spin {
  to {
    transform: rotate(360deg);
  }
}
.ec-cr-cloud-icon--local_ahead,
.ec-cr-cloud-icon--local_only,
.ec-cr-cloud-icon--checking,
.ec-cr-cloud-icon--failed,
.ec-cr-cloud-icon--invalid {
  color: var(--wb-color-text-primary);
}
.ec-cr-cloud-icon--cloud_ahead,
.ec-cr-cloud-icon--cloud_only,
.ec-cr-cloud-icon--both {
  color: var(--wb-color-text-primary);
}
.ec-cr-card:hover .ec-cr-more-btn--top,
.ec-cr-card:focus-within .ec-cr-more-btn--top,
.ec-cr-card .ec-cr-more-btn--top.is-visible {
  opacity: 1;
  pointer-events: auto;
}
.ec-cr-more-btn {
  position: absolute;
  top: 16px;
  right: calc(var(--wb-spacing-12) + var(--wb-spacing-8));
  z-index: 3;
  width: var(--wb-spacing-7);
  height: 24px;
  border: none;
  border-radius: 8px;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--wb-color-text-secondary);
  transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease;
  flex-shrink: 0;
  padding: 0;
  opacity: 0;
  pointer-events: none;
}
.ec-cr-more-btn:hover {
  background: rgba(0, 0, 0, 0.06);
  color: var(--wb-color-text-primary);
}
/* 右键菜单 */
.ec-cr-context-menu {
  position: absolute;
  right: calc(var(--wb-spacing-12) + var(--wb-spacing-8));
  top: 44px;
  background: var(--wb-bg-popover);
  border-radius: 14px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15), 0 8px 20px rgba(0, 0, 0, 0.1);
  padding: 6px 2px;
  z-index: 100;
  min-width: 110px;
  display: none;
  border: 1px solid var(--wb-border-default);
}
.expert-center-dark .ec-cr-context-menu {
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4), 0 8px 20px rgba(0, 0, 0, 0.25);
}
.ec-cr-context-menu.is-visible {
  display: block;
  animation: ec-ctx-in 0.2s ease-out;
}
@keyframes ec-ctx-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.ec-cr-ctx-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 4px 12px;
  border: none;
  background: transparent;
  color: var(--wb-color-text-primary, rgba(0, 0, 0, 0.9));
  font-family: "PingFang SC";
  font-size: 13px;
  font-weight: 400;
  font-style: normal;
  line-height: 22px;
  text-align: left;
  text-decoration-line: none;
  cursor: pointer;
  transition: background 0.15s ease;
}
.ec-cr-ctx-item:hover {
  background: rgba(0, 0, 0, 0.06);
  border-radius: 8px;
}
.ec-cr-ctx-item.is-danger {
  color: var(--wb-color-text-primary, rgba(0, 0, 0, 0.9));
}
.ec-cr-ctx-item.is-danger:hover {
  background: rgba(0, 0, 0, 0.06);
}
.ec-cr-ctx-item svg,
.ec-cr-ctx-icon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
.ec-cr-ctx-icon {
  display: block;
}
.ec-cr-ctx-item:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}
/* ===== 专家分享弹框 ===== */
.ec-share-modal-card .ec-share-body {
  padding: 0 20px 16px;
}
.ec-share-modal-card .ec-share-footer {
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  gap: 8px;
}
.ec-share-modal-card .ec-share-copy-btn {
  justify-content: center;
}
.ec-share-footer-tip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--wb-color-text-secondary);
  text-align: center;
}
.ec-share-footer-tip svg {
  width: 13px;
  height: 13px;
  flex-shrink: 0;
  color: var(--wb-status-warning-muted);
}
.ec-share-modal {
  background: var(--wb-bg-card);
  border-radius: 16px;
  width: min(540px, calc(100vw - 48px));
  max-height: min(680px, calc(100vh - 48px));
  display: flex;
  flex-direction: column;
  position: relative;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.12), 0 8px 32px rgba(0, 0, 0, 0.08);
  overflow: hidden;
}
.ec-share-title {
  margin: 0;
  padding: 24px 48px 0 24px;
  font-size: 16px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  line-height: 1.4;
  flex-shrink: 0;
}
.ec-share-title-name {
  color: var(--wb-brand-accent);
}
.ec-share-warning {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 16px 24px 0;
  padding: 10px 14px;
  border-radius: 10px;
  background: var(--wb-alert-warning-bg);
  color: var(--wb-badge-gold-fg);
  font-size: 12px;
  line-height: 1.5;
  flex-shrink: 0;
}
.ec-share-warning svg {
  flex-shrink: 0;
  color: var(--wb-badge-gold);
}
.expert-center-dark .ec-share-warning {
  background: rgba(212, 160, 23, 0.12);
  color: var(--wb-badge-gold-bg);
}
.expert-center-dark .ec-share-warning svg {
  color: var(--wb-badge-gold-bg);
}
.ec-share-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.ec-share-section {
  border: 1px solid var(--wb-border-default);
  border-radius: 12px;
  overflow: hidden;
}
.ec-share-section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 12px 14px;
  border: none;
  background: transparent;
  cursor: pointer;
  color: var(--wb-color-text-primary);
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  transition: background 0.15s ease;
}
.ec-share-section-header:hover {
  background: var(--wb-brand-accent-bg);
}
.ec-share-section-icon {
  display: flex;
  align-items: center;
  color: var(--wb-color-text-tertiary);
}
.ec-share-section-label {
  flex: 1;
}
.ec-share-section-toggle {
  display: flex;
  align-items: center;
  color: var(--wb-color-text-tertiary);
}
.ec-share-prompt-content {
  padding: 0 14px 14px;
  font-size: 13px;
  line-height: 1.7;
  color: var(--wb-color-text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 200px;
  overflow-y: auto;
  border-top: 1px solid var(--wb-border-default);
  margin-top: 0;
  padding-top: 12px;
  background: color-mix(in srgb, var(--wb-bg-card) 50%, transparent);
}
.ec-share-skills-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0 14px 14px;
  border-top: 1px solid var(--wb-border-default);
  padding-top: 12px;
}
.ec-share-skill-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 20px;
  border: 1.5px solid var(--wb-brand-accent);
  color: var(--wb-brand-accent);
  font-size: 12px;
  font-weight: 500;
  background: transparent;
  white-space: nowrap;
}
.ec-share-skill-chip svg {
  width: 13px;
  height: 13px;
}
.ec-share-footer {
  display: flex;
  justify-content: flex-end;
  padding: 16px 24px 20px;
  flex-shrink: 0;
}
.ec-share-copy-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 28px;
  border-radius: 10px;
  border: none;
  background: var(--wb-brand-accent);
  color: var(--wb-button-primary-fg);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.15s ease;
}
.ec-share-copy-btn:hover {
  opacity: 0.9;
}
.ec-share-copy-btn:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}
.ec-share-copy-btn svg {
  flex-shrink: 0;
}
.ec-share-spinner {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: var(--wb-border-default);
  animation: ec-share-spinner-rotate 0.8s linear infinite;
  flex-shrink: 0;
}
@keyframes ec-share-spinner-rotate {
  to {
    transform: rotate(360deg);
  }
}
/* ===== 专家导入确认弹框 ===== */
.expert-import-modal-overlay {
  background: color-mix(in srgb, var(--wb-bg-secondary) 78%, transparent);
}
.expert-import-modal-shell {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 28px;
  max-width: 90vw;
  max-height: calc(100vh - 40px);
}
.expert-import-modal-heading {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--wb-color-text-primary);
  text-align: center;
}
.expert-import-modal-card .ec-modal-close:disabled,
.expert-import-modal-card .ec-modal-summon-btn:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}
.expert-import-loading-card {
  width: 360px;
  min-height: 160px;
  justify-content: center;
}
.expert-import-loading-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 24px;
}
.expert-import-loading-spinner {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--wb-text-muted) 24%, transparent);
  border-top-color: var(--wb-color-text-primary);
  animation: ec-share-spinner-rotate 0.8s linear infinite;
}
.expert-import-loading-text {
  color: var(--wb-color-text-secondary);
  font-size: 13px;
  line-height: 1.5;
  text-align: center;
}
.expert-import-security-card {
  position: relative;
  width: min(560px, calc(100vw - 48px));
  padding: 28px 32px 30px;
  border-radius: 16px;
  background: var(--wb-bg-card);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.18), 0 8px 32px rgba(0, 0, 0, 0.1);
}
.expert-import-security-close {
  position: absolute;
  top: 20px;
  right: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-color-text-tertiary);
  cursor: pointer;
}
.expert-import-security-close:hover {
  background: var(--wb-bg-secondary);
  color: var(--wb-color-text-primary);
}
.expert-import-security-title {
  margin: 4px 40px 24px 0;
  color: var(--wb-color-text-primary);
  font-size: 20px;
  font-weight: 600;
  line-height: 1.4;
}
.expert-import-security-status-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 132px;
  margin-bottom: 22px;
  border: 1px dashed var(--wb-border-default);
  border-radius: 14px;
  background: color-mix(in srgb, var(--wb-bg-card) 70%, transparent);
}
.expert-import-security-hourglass {
  margin-bottom: 10px;
  font-size: 30px;
  line-height: 1;
}
.expert-import-security-status-text {
  color: var(--wb-color-text-primary);
  font-size: 15px;
  font-weight: 600;
  line-height: 1.5;
}
.expert-import-security-desc {
  margin-bottom: 18px;
  color: var(--wb-color-text-secondary);
  font-size: 14px;
  line-height: 1.7;
}
.expert-import-security-checkbox {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 22px;
  color: var(--wb-color-text-secondary);
  font-size: 14px;
  line-height: 1.5;
  cursor: pointer;
}
.expert-import-security-checkbox input {
  width: 18px;
  height: 18px;
  margin: 0;
  cursor: pointer;
}
.expert-import-security-footer {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.expert-import-security-skip-btn {
  min-width: 176px;
  height: 40px;
  padding: 0 20px;
  border: 1px solid var(--wb-border-default);
  border-radius: 10px;
  background: var(--wb-bg-card);
  color: var(--wb-color-text-primary);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.expert-import-security-skip-btn:hover {
  border-color: var(--wb-brand-accent);
  color: var(--wb-brand-accent);
}
.expert-import-security-skip-tip {
  color: var(--wb-color-text-tertiary);
  font-size: 12px;
  line-height: 1.5;
  text-align: center;
}
.expert-import-dialog-detail {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.expert-import-dialog-prompt {
  border: 1px solid var(--wb-border-default);
  border-radius: 12px;
  overflow: hidden;
  background: var(--wb-bg-card);
}
.expert-import-dialog-section-title {
  padding: 10px 12px;
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  border-bottom: 1px solid var(--wb-border-default);
}
.expert-import-dialog-prompt-content {
  padding: 12px;
  max-height: 180px;
  overflow-y: auto;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 13px;
  line-height: 1.7;
  color: var(--wb-color-text-secondary);
}
.expert-import-dialog-error {
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--wb-bg-error-soft);
  color: var(--wb-alert-error-text);
  font-size: 12px;
  line-height: 1.5;
}
.expert-center-dark .expert-import-dialog-error {
  background: rgba(248, 113, 113, 0.1);
  color: var(--wb-status-error);
}
/* 状态标签 */
.ec-cr-status-badge {
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 6px;
  white-space: nowrap;
  flex-shrink: 0;
}
.ec-cr-status-badge.is-unpublished {
  background: var(--wb-bg-tertiary);
  color: var(--wb-color-text-tertiary);
}
.ec-cr-status-badge.is-reviewing {
  background: var(--wb-alert-warning-bg);
  color: var(--wb-badge-warning-fg);
}
.ec-cr-status-badge.is-published {
  background: var(--wb-alert-success-bg);
  color: var(--wb-alert-success-text);
}
.ec-cr-status-badge.is-rejected {
  background: var(--wb-bg-error-soft);
  color: var(--wb-alert-error-text);
}
.ec-cr-status-badge.is-new-version {
  background: var(--wb-alert-info-bg);
  color: var(--wb-alert-info-text);
}
/* 我创建的空态 */
.ec-my-created-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px;
}
.ec-my-created-empty-icon {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.ec-my-created-empty-icon svg {
  width: 56px;
  height: 56px;
  stroke: var(--wb-color-text-primary);
  stroke-width: 1.5;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.ec-my-created-empty-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin: 0 0 8px;
  letter-spacing: -0.2px;
}
.ec-my-created-empty-hint {
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
  margin: 0 0 24px;
  font-weight: 400;
  line-height: 1.6;
}
.ec-my-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 40px;
  color: var(--wb-color-text-tertiary);
}
.ec-my-empty .ec-empty-icon {
  width: 64px;
  height: 64px;
  margin-bottom: 18px;
  color: var(--wb-border-default);
}
.ec-my-empty-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--wb-color-text-secondary);
}
.ec-my-empty-hint {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
}
/* ===== 响应式 ===== */
@media (max-width: 1279px) {
  .ec-card-grid,
  .ec-expert-grid,
  .ec-my-grid,
  .ec-official-section .ec-expert-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .ec-my-grid.is-search-empty {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .ec-my-grid.is-search-empty .ec-create-card {
    grid-column: 2;
  }
}
@media (max-width: 991px) {
  .ec-card-grid,
  .ec-expert-grid,
  .ec-my-grid,
  .ec-official-section .ec-expert-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .ec-my-grid.is-search-empty {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ec-my-grid.is-search-empty .ec-create-card {
    grid-column: 1 / -1;
    width: calc((100% - 12px) / 2);
    justify-self: center;
  }
}
@media (max-width: 767px) {
  .expert-center-page {
    --ec-page-gutter: 20px;
    --ec-content-gutter: 20px;
  }
  .ec-page-header {
    padding: 16px var(--ec-content-gutter) 12px;
    gap: 12px;
  }
  .ec-main-tab {
    font-size: 16px;
  }
  .ec-recruit-banner {
    min-height: 100px;
  }
  .ec-recruit-title {
    font-size: 16px;
  }
  .ec-card-grid,
  .ec-expert-grid,
  .ec-my-grid,
  .ec-official-section .ec-expert-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
  .ec-search-wrapper {
    width: 200px;
    min-width: 160px;
  }
}
@media (max-width: 575px) {
  .ec-card-grid,
  .ec-expert-grid,
  .ec-my-grid,
  .ec-official-section .ec-expert-grid {
    grid-template-columns: 1fr;
  }
  .ec-my-grid.is-search-empty {
    grid-template-columns: minmax(0, 1fr);
  }
  .ec-my-grid.is-search-empty .ec-create-card {
    grid-column: 1;
    width: 100%;
  }
}
/* ===== 专家详情弹窗 ===== */
.ec-detail-mask {
  position: fixed;
  inset: 0;
  /* 蒙层颜色统一走 foundation token，不再自定义颜色与背景模糊（#49111） */
  background: var(--wb-color-mask-color);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s, visibility 0.3s;
}
.ec-detail-mask.is-visible {
  opacity: 1;
  visibility: visible;
}
.ec-detail-modal {
  background: var(--wb-bg-card);
  border-radius: 16px;
  width: 520px;
  max-height: 80vh;
  overflow-y: auto;
  position: relative;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.18);
  transform: translateY(20px) scale(0.96);
  transition: transform 0.3s;
}
.ec-detail-mask.is-visible .ec-detail-modal {
  transform: translateY(0) scale(1);
}
.ec-detail-modal::-webkit-scrollbar {
  width: 4px;
}
.ec-detail-modal::-webkit-scrollbar-thumb {
  background: var(--wb-border-default);
  border-radius: 2px;
}
/* 关闭按钮 */
.ec-detail-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: none;
  background: rgba(0, 0, 0, 0.06);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
  z-index: 2;
}
.ec-detail-close:hover {
  background: rgba(0, 0, 0, 0.12);
}
.ec-detail-close svg {
  width: 16px;
  height: 16px;
  stroke: var(--wb-color-text-secondary);
}
/* Header */
.ec-detail-header {
  text-align: center;
  padding: 32px 32px 0;
}
.ec-detail-avatar {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  object-fit: cover;
  margin: 0 auto 12px;
  display: block;
  border: 3px solid var(--wb-tab-active-border);
}
.ec-detail-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin: 0 0 2px;
}
.ec-detail-title {
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
  margin: 0 0 10px;
}
.ec-detail-desc {
  font-size: 13px;
  color: var(--wb-color-text-secondary);
  line-height: 1.6;
  margin: 0 0 20px;
  padding: 0 8px;
}
/* Meta 行 */
.ec-detail-meta {
  display: flex;
  justify-content: center;
  gap: 0;
  padding: 16px 24px;
  margin: 0 24px;
  border-top: 1px solid var(--wb-border-default);
  border-bottom: 1px solid var(--wb-border-default);
}
.ec-detail-meta-item {
  flex: 1;
  text-align: center;
  padding: 0 8px;
}
.ec-detail-meta-item:not(:last-child) {
  border-right: 1px solid var(--wb-border-default);
}
.ec-detail-meta-val {
  font-size: 14px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin-bottom: 2px;
}
.ec-detail-meta-label {
  font-size: 11px;
  color: var(--wb-color-text-tertiary);
}
/* 具体能力介绍 */
.ec-detail-section {
  padding: 20px 32px 0;
}
.ec-detail-section h3 {
  font-size: 15px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin: 0 0 12px;
}
.ec-detail-abilities {
  list-style: none;
  padding: 0;
  margin: 0 0 20px;
}
.ec-detail-abilities li {
  font-size: 13px;
  color: var(--wb-color-text-primary);
  line-height: 1.7;
  padding: 6px 0 6px 20px;
  position: relative;
}
.ec-detail-abilities li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 13px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--wb-brand-accent);
}
.ec-detail-abilities-empty {
  color: var(--wb-color-text-tertiary);
  font-style: italic;
}
.ec-detail-abilities-empty::before {
  display: none;
}
/* 使用技能 */
.ec-detail-skills {
  padding: 0 32px 16px;
}
.ec-detail-skills h3 {
  font-size: 15px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin: 0 0 12px;
}
.ec-detail-skills-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.ec-detail-skill-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  background: linear-gradient(135deg, #f5f2ff, #ede5ff);
  color: var(--wb-brand-accent);
  border: 1px solid rgba(124, 92, 252, 0.12);
  transition: background 0.2s, border-color 0.2s;
}
.ec-detail-skill-tag:hover {
  background: linear-gradient(135deg, #ede5ff, #e0d4ff);
  border-color: rgba(124, 92, 252, 0.25);
}
.ec-detail-skill-tag svg {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
}
.ec-detail-skills-empty {
  font-size: 12px;
  color: var(--wb-color-text-tertiary);
  font-style: italic;
}
/* Footer: 立即召唤 */
.ec-detail-footer {
  padding: 16px 32px 24px;
  position: sticky;
  bottom: 0;
  background: var(--wb-bg-card);
  border-top: 1px solid var(--wb-border-default);
}
.ec-detail-summon {
  width: 100%;
  padding: 13px 0;
  border: none;
  border-radius: 10px;
  font-size: 15px;
  font-weight: 700;
  color: var(--wb-button-primary-fg);
  background: linear-gradient(135deg, var(--wb-brand-accent), var(--wb-brand-accent));
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
  box-shadow: 0 4px 14px rgba(124, 92, 252, 0.3);
  letter-spacing: 0.5px;
}
.ec-detail-summon:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(124, 92, 252, 0.3), 0 6px 20px rgba(124, 92, 252, 0.25);
}
/* 暗色主题适配 */
.expert-center-dark .ec-detail-modal {
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.4);
}
.expert-center-dark .ec-detail-close {
  background: rgba(255, 255, 255, 0.1);
}
.expert-center-dark .ec-detail-close:hover {
  background: rgba(255, 255, 255, 0.18);
}
.expert-center-dark .ec-detail-close svg {
  stroke: var(--wb-color-text-tertiary);
}
.expert-center-dark .ec-detail-avatar {
  border-color: var(--wb-accent-purple-light);
}
.expert-center-dark .ec-detail-desc {
  color: var(--wb-color-text-tertiary);
}
.expert-center-dark .ec-detail-abilities li {
  color: var(--wb-color-text-disabled);
}
.expert-center-dark .ec-detail-skill-tag {
  background: linear-gradient(135deg, #2d2a3e, #3a3550);
  border-color: rgba(124, 92, 252, 0.2);
}
.expert-center-dark .ec-detail-skill-tag:hover {
  background: linear-gradient(135deg, #3a3550, #4a4065);
}
/* issue: #57374 主题切换时禁用 background transition，避免闪烁 */
:root.theme-switching .ec-expert-card,
body.theme-switching .ec-expert-card,
:root.theme-switching .ec-category-tab,
body.theme-switching .ec-category-tab,
:root.theme-switching .ec-sort-btn,
body.theme-switching .ec-sort-btn,
:root.theme-switching .wb-button,
body.theme-switching .wb-button {
  transition: none;
}
